//! Lower IR to asm6502 assembly text.
//!
//! Each BASIC line gets its own label `Lnnnnn`, so GOTO/GOSUB jumps
//! between lines without us doing any address fixup — the assembler
//! resolves it via two-pass label resolution.
//!
//! Numeric values flow through BASIC's FAC1 (Floating Accumulator).
//! Expressions evaluate post-order: for `lhs OP rhs` we evaluate `rhs`
//! first into FAC, push the result to a stack-allocated temp slot, then
//! evaluate `lhs` into FAC and apply the binary op with the temp as
//! memory operand. This works uniformly for `+ - * /` because BASIC's
//! FADD/FSUB/FMULT/FDIV all compute `FAC = FAC OP mem[A,Y]` — the
//! operand is the second one, which is exactly what we stored.
//!
//! Comparison ops produce -1.0 (true) / 0.0 (false) per BASIC v2 by
//! routing FCOMP's signum through GIVAYF.
//!
//! FOR/NEXT: each FOR pushes a frame on a compile-time stack and
//! allocates a per-loop slot for END (the loop bound). The STEP value
//! is required to be a literal at lower-time so its sign — which decides
//! the loop-exit comparison direction — is known statically; it's
//! interned in the float constant pool like any other literal.

use std::collections::{HashMap, HashSet};
use std::fmt::Write as _;

use crate::ast::{
    self, BinOp, DataValue, FnName, Func1, OnBranchKind, ScreenRectOp, ScreenScrollOp, VarKind,
    VarName,
};
use crate::ir::{
    self, ArrayInduction, ArrayInductionIndex, Expr, MemTransferOp, PrintPiece, ReadTarget, Stmt,
    StrExpr, ThenIr,
};
use crate::ISSUES_URL;
use crate::for_next_runtime::OrphanAnalysis;
use crate::runtime as rt;

mod sys_strings;
mod shadow_mirrors;

/// Where the machine code lives in memory after the SYS stub. Keep in
/// sync with `pack.rs`. Used when `CompileOptions::custom_start_address`
/// is `None`; otherwise the user-supplied address takes over and the
/// SYS launcher is omitted from the packed .prg.
pub const CODE_ORIGIN: u16 = 0x080D;

/// Hard ceiling on the runtime FOR-stack, in entries (one byte per entry in each of the two
/// parallel arrays).
const AUTO_DIM_BOUND: u16 = 10;

/// Size of `__USE_BUF` for a `USE` control string built at run time.
/// TSB raises ?STRING TOO LONG past this.
const USE_DYN_BUF_LEN: u8 = 88;

/// Extra BSS, in bytes, `grow_static_arrays_for_clr` may spend across the whole module widening
/// static arrays to the auto-`DIM` bound a `CLR` restores.
const CLR_REDIM_GROWTH_BUDGET: u32 = 1024;

const FOR_STACK_DEPTH_MAX: usize = 32;

/// Maximum FOR nesting that leaves room to evaluate an expression.
pub(crate) const FOR_NEST_EXPR_MAX: usize = (BASIC_STACK_BUDGET / FOR_FRAME_BYTES) as usize;

/// Spare entries added to the computed per-program bound.
const FOR_STACK_DEPTH_MARGIN: usize = 2;

/// BASIC page-1 stack limits and frame sizes.
const BASIC_STACK_BASE: u32 = 180;

/// Statement stack costs, subtracted from BASIC_STACK_BASE.
const HOST_COST_GOSUB_PUSH: u32 = 1;
const HOST_COST_LET: u32 = 2;
const HOST_COST_ON: u32 = 4;

const HOST_COST_POKE: u32 = 4;
const HOST_COST_FOR: u32 = 11;

/// Stack costs for expression nodes.
const EXPR_COST_PAREN: u32 = 5;
const EXPR_COST_FUNC: u32 = 8;
const EXPR_COST_OP: u32 = 12;
const EXPR_COST_USER_FN: u32 = 16;

/// Stack budget used to bound FOR nesting and runtime stack allocation.
const BASIC_STACK_BUDGET: u32 = 167;

/// Maximum stack floor shared by runtime checks.
const BASIC_STACK_CAP: u8 = (BASIC_STACK_BUDGET + 1) as u8;

/// Bytes one `GOSUB` level costs on BASIC's stack.
const GOSUB_FRAME_BYTES: u32 = 7;
/// Bytes a `FOR` record occupies on BASIC's stack.
const FOR_FRAME_BYTES: u32 = 18;

const GOSUB_DEPTH_FLOOR: u32 = 6;
/// Maximum GOSUB depth allowed by the hardware stack guard.
const GOSUB_DEPTH_CEIL: u8 = 40;
/// Lowest 6502 stack pointer a re-entrant `DEF FN` body may run at.
const FN_STACK_FLOOR: u8 = 0x20;

// Trailing zero data is initialized at startup and omitted from the load image.

/// Line `finish()` rewrites into the fill loop (or deletes).
const BSS_FILL_MARKER: &str = "; @@BSS_TAIL_FILL@@";
/// Last line of the fill block.
const BSS_FILL_CLOSE: &str = "; --- end BSS zero-fill ---";
/// Marker replaced with variable and array clearing code.
const STATE_ZERO_MARKER: &str = "; @@STATE_ZERO@@";
/// Entry state initialization markers.
const STATE_INIT_OPEN: &str = "; @@STATE_INIT@@";
const STATE_INIT_CLOSE: &str = "; @@END_STATE_INIT@@";
/// Marker replaced with state clearing code.
const STATE_RESET_ZERO_MARKER: &str = "; @@STATE_RESET_ZERO@@";
/// Clearing code used when the zero fill is removed.
pub(crate) const IF_NO_FILL_PREFIX: &str = ";@@IF_NO_FILL@@ ";
/// DATA cursor storage for programs that use SYS or USR.
const DATA_CUR_LABEL: &str = "__DATA_CUR";
/// Markers for the alternative VAL helpers and their buffer.
pub(crate) const VAL_COPY_OPEN: &str = "; @@VAL_COPY_OPEN@@";
pub(crate) const VAL_COPY_CLOSE: &str = "; @@VAL_COPY_CLOSE@@";
pub(crate) const VAL_INPLACE_OPEN: &str = "; @@VAL_INPLACE_OPEN@@";
pub(crate) const VAL_INPLACE_CLOSE: &str = "; @@VAL_INPLACE_CLOSE@@";
pub(crate) const VAL_BUF_OPEN: &str = "; @@VAL_BUF_OPEN@@";
pub(crate) const VAL_BUF_CLOSE: &str = "; @@VAL_BUF_CLOSE@@";

/// Opens the truncatable run.
pub const BSS_START_LABEL: &str = "__BSS_START";

/// Restores the index-context flag when an index or address lowering ends.
struct IndexContextGuard(std::rc::Rc<std::cell::Cell<bool>>, bool);

impl Drop for IndexContextGuard {
    fn drop(&mut self) {
        self.0.set(self.1);
    }
}
/// One past the last truncatable byte.
pub const BSS_END_LABEL: &str = "__BSS_END";
/// Expected byte count of the unrolled zero fill.
pub const BSS_FILL_SPAN_LABEL: &str = "BSS__FILL_SPAN";
/// Size of [`bss_fill_block`], the one a fill pays against.
const BSS_FILL_LOOP_BYTES: usize = 37;
/// Most pages the speed profile's fill stores one by one.
const BSS_FILL_UNROLL_PAGES: usize = 32;
/// Minimum byte saving required to omit trailing zeros.
const BSS_FILL_MIN_BYTES: usize = 64;

/// End marker for the contiguous DATA pool.
pub const DATA_POOL_CLOSE: &str = "__DATA_END:";

/// DATA address in RAM under I/O and KERNAL ROM.
pub const DATA_RUN_ADDR: u16 = 0xD000;
/// A relocated pool ends below the CPU vectors, which hold its NMI stub's address.
pub const DATA_RUN_LIMIT: u32 = 0xFFFA;
/// Load address set after linking.
pub const DATA_LOAD_LABEL: &str = "__DATA_LOAD";
/// The page a READ of a relocated pool copies its item into.
pub const DATA_BUF_LABEL: &str = "D__DATA_BUF";
/// Letter prefix for relocated DATA equates.
pub const RELOCATED_PREFIX: &str = "D";
/// Marker for DATA bytes appended to the output.
pub const DATA_BLOB_MARKER: &str = "; @@DATA_BLOB@@ ";

/// Where READ copies an item from a relocated DATA pool.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DataBuf {
    /// A free page outside the image.
    At(u16),
    /// A page of BSS.
    Bss,
}

#[derive(Debug)]
pub enum CodegenError {
    Unsupported(&'static str),
    UnmatchedNext {
        line: u16,
    },
    UnopenedFor {
        line: u16,
    },
    UnmatchedUntil {
        line: u16,
    },
    UnmatchedEndLoop {
        line: u16,
    },
    ExitWithoutLoop {
        line: u16,
    },
    DoneWithoutDo {
        line: u16,
    },
    ElseWithoutDo {
        line: u16,
    },
    /// Reserved error for `NEXT name` that names a different variable
    /// than the matching `FOR`. The current frontend rewrites all
    /// `NEXT` lists into anonymous closes, so this never fires; kept
    /// to preserve the wire-format of the error enum for tooling.
    #[allow(dead_code)]
    NextVarMismatch {
        line: u16,
        expected: String,
        got: String,
    },
    StringInNumericContext,
    UndimensionedArray(String),
    DuplicateDim(String),

    ArrayDimMismatch {
        name: String,
        expected: usize,
        got: usize,
    },
    UndefinedFn(String),
    DuplicateDefFn(String),
    /// The runtime handler or variable ID exceeds one byte.
    ForNextIdSpaceExhausted {
        what: &'static str,
    },
}

impl std::fmt::Display for CodegenError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CodegenError::Unsupported(w) => write!(f, "{w} not yet supported"),
            CodegenError::UnmatchedNext { line } => write!(f, "line {line}: NEXT without FOR"),
            CodegenError::UnopenedFor { line } => {
                write!(f, "line {line}: FOR not closed by NEXT")
            }
            CodegenError::UnmatchedUntil { line } => write!(f, "line {line}: UNTIL without REPEAT"),
            CodegenError::UnmatchedEndLoop { line } => {
                write!(f, "line {line}: END LOOP without LOOP")
            }
            CodegenError::ExitWithoutLoop { line } => write!(f, "line {line}: EXIT without loop"),
            CodegenError::DoneWithoutDo { line } => write!(f, "line {line}: DONE without DO"),
            CodegenError::ElseWithoutDo { line } => write!(f, "line {line}: ELSE without DO"),
            CodegenError::NextVarMismatch {
                line,
                expected,
                got,
            } => write!(
                f,
                "line {line}: NEXT {got} doesn't match innermost FOR {expected}"
            ),
            CodegenError::StringInNumericContext => {
                write!(f, "string value used where number was expected")
            }
            CodegenError::UndimensionedArray(name) => {
                write!(f, "array {name} used without DIM")
            }
            CodegenError::DuplicateDim(name) => {
                write!(f, "array {name} declared with DIM more than once")
            }
            CodegenError::ArrayDimMismatch {
                name,
                expected,
                got,
            } => write!(
                f,
                "array {name}: declared with {expected} dimension(s), used with {got}",
            ),
            CodegenError::UndefinedFn(name) => {
                write!(f, "FN {name} called without a matching DEF FN")
            }
            CodegenError::DuplicateDefFn(name) => {
                write!(f, "DEF FN {name} declared more than once")
            }
            CodegenError::ForNextIdSpaceExhausted { what } => write!(
                f,
                "too many {what}: the runtime FOR/NEXT dispatcher indexes them \
                 with a single byte, so 255 is the hard limit"
            ),
        }
    }
}

impl std::error::Error for CodegenError {}

pub fn emit_with_profile(module: &ir::Module, profile: Profile) -> Result<String, CodegenError> {
    emit_with_profile_at(module, profile, CODE_ORIGIN)
}

/// Same as [`emit_with_profile`] but the caller picks the origin. Used
/// by the `custom_start_address` path to relocate code away from $080D.
pub fn emit_with_profile_at(
    module: &ir::Module,
    profile: Profile,
    origin: u16,
) -> Result<String, CodegenError> {
    emit_with_profile_at_opts(
        module,
        profile,
        origin,
        false,
        &crate::rem_hints::VarTypeHints::default(),
    )
}

/// Full form: includes `safe_sys_calls` plus REM-hint sets that
/// force-promote named vars to byte storage and bias them into the
/// ZP pool regardless of what the dataflow analysis would have
/// chosen on its own.
pub fn emit_with_profile_at_opts(
    module: &ir::Module,
    profile: Profile,
    origin: u16,
    safe_sys_calls: bool,
    hints: &crate::rem_hints::VarTypeHints,
) -> Result<String, CodegenError> {
    emit_with_profile_at_opts_diag(
        module,
        profile,
        origin,
        safe_sys_calls,
        hints,
        &HashMap::new(),
    )
    .map(|(asm, _)| asm)
}

/// Like [`emit_with_profile_at_opts`], additionally returning the zero-page pool pressure
/// counters so callers can surface them in compile diagnostics.
pub fn emit_with_profile_at_opts_diag(
    module: &ir::Module,
    profile: Profile,
    origin: u16,
    safe_sys_calls: bool,
    hints: &crate::rem_hints::VarTypeHints,
    poisoned_fns: &HashMap<FnName, u8>,
) -> Result<(String, ZpPressure), CodegenError> {
    emit_with_profile_at_opts_diag_and_source_types(
        module,
        profile,
        origin,
        safe_sys_calls,
        hints,
        poisoned_fns,
        SourceIntegerVars::from_module(module),
    )
}

/// Key for shared integer equality code.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
enum EqTailKey {
    /// `v = k`.
    VarConst(VarName, i32),
    /// `v = w`.
    VarVar(VarName, VarName),
}

impl EqTailKey {
    fn of(a: &Expr, b: &Expr) -> Option<Self> {
        match (a, b) {
            (Expr::Var(v), Expr::Number(n)) if n.fract() == 0.0 => {
                Some(Self::VarConst(v.clone(), *n as i32))
            }
            (Expr::Var(v), Expr::Var(w)) => Some(Self::VarVar(v.clone(), w.clone())),
            _ => None,
        }
    }
}

/// Counts the `=`/`<>` expressions per [`EqTailKey`].
#[derive(Default)]
struct EqualityTailSites(HashMap<EqTailKey, usize>);

impl crate::visit::Visitor for EqualityTailSites {
    fn visit_expr(&mut self, expr: &Expr) {
        if let Expr::Bin(BinOp::Eq | BinOp::Ne, a, b) = expr
            && let Some(key) = EqTailKey::of(a, b)
        {
            *self.0.entry(key).or_default() += 1;
        }
        crate::visit::walk_expr(self, expr);
    }
}

impl EqualityTailSites {
    fn count(module: &ir::Module) -> HashMap<EqTailKey, usize> {
        let mut sites = Self::default();
        crate::visit::walk_module(&mut sites, module);
        sites.0
    }
}

/// Counts the targets of every READ statement.
#[derive(Default)]
struct ReadTargets(usize);

impl crate::visit::Visitor for ReadTargets {
    fn visit_stmt(&mut self, line_no: u16, stmt: &Stmt) {
        if let Stmt::Read(targets) = stmt {
            self.0 += targets.len();
        }
        crate::visit::walk_stmt(self, line_no, stmt);
    }
}

impl ReadTargets {
    fn count(module: &ir::Module) -> usize {
        let mut targets = Self::default();
        crate::visit::walk_module(&mut targets, module);
        targets.0
    }
}

/// Track scalar writes to estimate runtime DIM sizes.
#[derive(Default)]
struct RuntimeDimDemand {
    latest: HashMap<VarName, Option<f64>>,
    /// Largest element count each array is DIMed with, and its rank.
    per_array: HashMap<VarName, (f64, usize)>,
}

impl crate::visit::Visitor for RuntimeDimDemand {
    fn visit_stmt(&mut self, line_no: u16, stmt: &Stmt) {
        let mut opaque = |var: &VarName| {
            self.latest.insert(var.clone(), None);
        };
        match stmt {
            Stmt::Let { var, value } => {
                let n = if let Expr::Number(n) = value { Some(*n) } else { None };
                self.latest.insert(var.clone(), n);
            }
            Stmt::For { var, start: Expr::Number(a), end: Expr::Number(b), .. } => {
                self.latest.insert(var.clone(), Some(a.max(*b)));
            }
            Stmt::Get { indices, .. } if !indices.is_empty() => {}
            Stmt::Fetch { target_indices, .. } if !target_indices.is_empty() => {}
            Stmt::For { var, .. } | Stmt::Get { var, .. } | Stmt::KeyGet { var } => opaque(var),
            Stmt::Fetch { target, .. } => opaque(target),
            Stmt::GetFile { vars, .. } => vars.iter().for_each(opaque),
            Stmt::Read(targets) | Stmt::Input { targets, .. } | Stmt::InputFile { targets, .. } => {
                for target in targets {
                    if let ReadTarget::Scalar(var) = target {
                        opaque(var);
                    }
                }
            }
            Stmt::Dim(specs) => {
                for spec in specs {
                    if spec.dims.iter().all(|d| matches!(d, Expr::Number(_))) {
                        continue;
                    }
                    let mut elements = 1.0;
                    for dim in &spec.dims {
                        match self.value(dim) {
                            Some(n) if (0.0..=65535.0).contains(&n) => elements *= n.floor() + 1.0,
                            _ => {
                                elements = 0.0;
                                break;
                            }
                        }
                    }
                    let entry = self.per_array.entry(spec.name.clone()).or_insert((0.0, 0));
                    *entry = (entry.0.max(elements), spec.dims.len());
                }
            }
            _ => {}
        }
        crate::visit::walk_stmt(self, line_no, stmt);
    }
}

impl RuntimeDimDemand {
    fn value(&self, expr: &Expr) -> Option<f64> {
        match expr {
            Expr::Number(n) => Some(*n),
            Expr::Var(var) => self.latest.get(var).copied().flatten(),
            Expr::Bin(op @ (BinOp::Add | BinOp::Sub | BinOp::Mul), l, r) => {
                let (l, r) = (self.value(l)?, self.value(r)?);
                Some(match op {
                    BinOp::Add => l + r,
                    BinOp::Sub => l - r,
                    _ => l * r,
                })
            }
            _ => None,
        }
    }
}

/// Array heap estimate for layout selection, not a runtime bound.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub(crate) struct RuntimeDimEstimate {
    /// Heap bytes in this compiler's layout.
    pub compiled: u32,
    /// Array heap use in BASIC.
    pub stock: u32,
}

pub(crate) fn runtime_dim_estimate(
    module: &ir::Module,
    source: &SourceIntegerVars,
) -> RuntimeDimEstimate {
    let mut demand = RuntimeDimDemand::default();
    crate::visit::walk_module(&mut demand, module);
    let (mut compiled, mut stock) = (0.0, 0.0);
    for (name, &(elements, rank)) in &demand.per_array {
        if elements == 0.0 {
            continue;
        }
        compiled += elements * Codegen::array_elem_size(name) as f64;
        let stock_elem = match name.kind {
            VarKind::String => 3.0,
            VarKind::Integer if source.arrays.contains(name) => 2.0,
            _ => 5.0,
        };
        stock += elements * stock_elem + 5.0 + 2.0 * rank as f64;
    }
    let clamp = |v: f64| v.min(f64::from(u32::MAX)) as u32;
    RuntimeDimEstimate {
        compiled: clamp(compiled),
        stock: clamp(stock),
    }
}

/// Original scalar and array namespaces are separate: `A%` does not make a demoted source `A()` an explicitly integer array, or conversely.
#[derive(Clone, Default)]
pub(crate) struct SourceIntegerVars {
    scalars: HashSet<VarName>,
    arrays: HashSet<VarName>,
}

impl crate::visit::Visitor for SourceIntegerVars {
    fn visit_expr(&mut self, expr: &Expr) {
        match expr {
            Expr::Var(var) if var.kind == VarKind::Integer => {
                self.scalars.insert(var.clone());
            }
            Expr::ArrayRef(var, _) if var.kind == VarKind::Integer => {
                self.arrays.insert(var.clone());
            }
            _ => {}
        }
        crate::visit::walk_expr(self, expr);
    }
}

impl SourceIntegerVars {
    pub(crate) fn from_module(module: &ir::Module) -> Self {
        let mut vars = Self::default();
        crate::visit::walk_module(&mut vars, module);
        vars
    }

    pub(crate) fn retain_live_arrays(&mut self, module: &ir::Module) {
        let live = Self::from_module(module);
        self.arrays.retain(|name| live.arrays.contains(name));
    }
}

/// The compiler supplies types captured before promotion; direct IR callers of the public emitter retain the kinds explicitly supplied in their IR.
pub(crate) fn emit_with_profile_at_opts_diag_and_source_types(
    module: &ir::Module,
    profile: Profile,
    origin: u16,
    safe_sys_calls: bool,
    hints: &crate::rem_hints::VarTypeHints,
    poisoned_fns: &HashMap<FnName, u8>,
    source_integer_vars: SourceIntegerVars,
) -> Result<(String, ZpPressure), CodegenError> {
    emit_with_profile_at_opts_diag_and_data_rescue(
        module,
        profile,
        origin,
        safe_sys_calls,
        hints,
        poisoned_fns,
        source_integer_vars,
        false,
        false,
        None,
        false,
        false,
    )
}

/// Enable compact code generation when ordinary layout cannot fit.
pub(crate) fn emit_with_profile_at_opts_diag_and_data_rescue(
    module: &ir::Module,
    profile: Profile,
    origin: u16,
    safe_sys_calls: bool,
    hints: &crate::rem_hints::VarTypeHints,
    poisoned_fns: &HashMap<FnName, u8>,
    source_integer_vars: SourceIntegerVars,
    compact_data_metadata: bool,
    // TSB dialect: boot like TSB, not a stock C64.
    tsb_target: bool,
    data_relocate: Option<DataBuf>,
    unchecked: bool,
    fast_float: bool,
) -> Result<(String, ZpPressure), CodegenError> {
    let analysis = CodegenAnalysis::from_module(module);
    let orphan_for_next = crate::for_next_runtime::analyze(module);
    // The runtime FOR/NEXT dispatcher indexes handlers and loop-var identities with one byte
    // each (0 reserved).
    if let Some(what) = orphan_for_next.id_space_exhausted {
        return Err(CodegenError::ForNextIdSpaceExhausted { what });
    }

    let candidates = analysis.numeric_facts.shadow_int_vars.clone();
    let bounded_accumulators = crate::passes::bounded_integer_accumulators(module);
    shadow_mirrors::emit_verified(candidates, |omitted| {
        let mut cg = Codegen::new(profile, analysis.clone());
        cg.omitted_float_slots = omitted.clone();
        cg.compact_data_metadata = compact_data_metadata;
        cg.source_integer_vars = source_integer_vars.clone();
        cg.bounded_accumulators = bounded_accumulators.clone();
        cg.code_origin = origin;
        cg.safe_sys_calls = safe_sys_calls;
        cg.tsb_target = tsb_target;
        cg.data_relocate = data_relocate;
        cg.unchecked = unchecked;
        cg.fast_float = fast_float;
        cg.forced_byte_bases = hints.byte_vars.clone();
        cg.forced_zp_bases = hints.zp_vars.clone();
        cg.poisoned_fns = poisoned_fns.clone();
        cg.orphan_for_next = orphan_for_next.clone();
        cg.run(module)?;
        let zp_pressure = cg.zp_pressure;
        let asm = cg.finish()?;
        Ok((asm, zp_pressure))
    })
}

/// Zero-page allocation counts and denied promotions.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct ZpPressure {
    /// Pool size right after the feature scan (`compute_zp_pool`).
    pub pool_initial: usize,
    /// Free bytes after zero-page allocation.
    pub pool_left: usize,
    /// Shadow-int candidates that fell back to a BSS slot (pool empty or the deliberate 2-slot
    /// shadow quota spent).
    pub shadow_denied: u32,
    /// Integer variables without a free or shareable zero-page slot.
    pub int_denied: u32,
    /// FOR counters without a free or shareable zero-page slot.
    pub counter_denied: u32,
    /// Runtime array bases left unpromoted when the pool ran dry.
    pub array_base_denied: u32,

    pub pool_lost_to_program: usize,
    /// Zero-page bytes the program may write / may read.
    pub program_zp_writes: usize,
    pub program_zp_reads: usize,
    /// Addresses proven to stay outside zero page.
    pub addrs_proved_clear: u32,
    /// Addresses narrowed to a strict subset of the page.
    pub addrs_narrowed: u32,
    /// Addresses that could be anywhere in the page.
    pub addrs_unprotectable: u32,
    /// `SYS` / `USR` sites.
    pub machine_code_calls: u32,
    /// Pointer pairs moved to avoid the program's zero-page access.
    pub pairs_relocated: u32,
    /// Pointer pairs with no free replacement location.
    pub pairs_unresolved: u32,
    /// The program's own `POKE`/`PEEK`/`WAIT` may reach MEMSIZ at `$37`/`$38`.
    pub program_touches_memsiz: bool,
    /// Runtime array demand beyond the string heap floor.
    pub runtime_dim_demand: u32,
}

impl ZpPressure {
    /// Total number of denied promotion candidates.
    pub fn denied_total(&self) -> u32 {
        self.shadow_denied + self.int_denied + self.counter_denied + self.array_base_denied
    }
}

// ===== Codegen state =====

struct Codegen {
    code: String,
    next_id: usize,
    strings: Vec<(String, Vec<u8>)>,
    /// A ROM VAL abort can leave its one-past-end NUL in place.
    val_literal_sentinels: HashSet<String>,
    /// f64 bit-pattern → label, for dedup of float constants.
    floats_index: HashMap<u64, String>,
    floats_order: Vec<(String, [u8; 5])>,
    vars_index: HashMap<VarName, String>,
    /// (label, byte-size). String vars are 2-byte pointer slots; floats
    /// are 5-byte MFLPT.
    vars_order: Vec<(String, usize)>,
    /// Per-slot in-use bitmap for the integer-island temp pool. Slot
    /// `i` holds 2 bytes at label `T<i>`. Tracked as a `Vec<bool>`
    /// (free-list) so out-of-order frees work correctly — the prior
    /// counter design assumed strict LIFO and aliased `T1` when a
    /// caller held it across a sub-evaluation that allocated and
    /// released its own temps. Caught by edge140
    /// (`t% + a%(i) + a%(i+5)` produced `2 * a%(i+5)` because the
    /// inner `i+5` evaluation alloc'd into the same `T1` slot the
    /// outer `t% + a%(i)` was still using as its result).
    temp_used: Vec<bool>,
    temp_max: usize,
    /// First DEF FN temporary slot, beyond all caller temporaries.
    fn_temp_base: usize,
    for_stack: Vec<ForFrame>,
    /// Most recently popped FOR frame, kept around so a stray NEXT
    /// (e.g. v2 idiom of multiple NEXTs sharing one FOR via
    /// `IF cond THEN ... NEXT : GOTO` plus a sibling outer NEXT) can
    /// re-emit loop continuation code rather than hitting an
    /// `UnmatchedNext` compile error.
    last_popped_for: Option<ForFrame>,
    /// Give each NEXT exit its own label.
    emitted_for_exits: HashSet<String>,
    /// The one frame a later stack-underflowing `NEXT` is allowed to re-emit.
    shared_next_candidate: Option<ForFrame>,
    /// Where each emitted `FOR` came from, keyed by its `__FOR_TOP_<n>` label (unique per
    /// emission, and preserved by `with_fresh_exit`).
    for_origin_by_top_label: HashMap<String, ForNextStmtId>,
    /// `__FOR_TOP_<n>` labels of loops whose body some transfer can jump into without running
    /// the header (`OrphanAnalysis::entered_fors`).
    externally_entered_for_tops: HashSet<String>,
    /// The binding selected by the last NEXT emission.
    last_next_binding: NextBinding,
    structured_loop_stack: Vec<StructuredLoopFrame>,
    do_stack: Vec<DoFrame>,
    /// Number of per-FOR END slots allocated so far. We never free them
    /// (not worth the bookkeeping for a few bytes).
    for_end_slots: usize,
    /// Address caches by float variable label and added constant, in id order.
    addr_caches: Vec<(String, u16)>,
    /// Float variables whose whole value in 0..=65535 is cached for `V+counter` addresses.
    addr_int_caches: Vec<String>,
    /// Integer sums per FOR statement, with a flag for runtime checks.
    wide_sum_plans: HashMap<crate::cfg::StmtPath, Vec<(VarName, bool)>>,
    /// FOR statements whose exit store precedes every read of the variable.
    dead_for_header_stores: HashSet<crate::cfg::StmtPath>,
    /// Float variables summed in a 24-bit slot inside the open loop with this top label.
    wide_sums: Vec<WideSum>,
    used_i24_fac: bool,
    used_ws_load: bool,
    used_cs_load_u: bool,
    used_cs_load_s: bool,
    used_cs_mf_u: bool,
    used_cs_mf_s: bool,
    /// `FOR N=a TO b:POKE N+K1,PEEK(N+K2):NEXT` lines lowered to a block copy, keyed by the FOR.
    copy_loop_plans: HashMap<crate::cfg::StmtPath, CopyLoop>,
    /// The copy the FOR being emitted stands for.
    pending_copy: Option<CopyLoop>,
    /// Number of dynamic-STEP sign slots allocated (1 byte each, named
    /// `FS_SIGN_<n>`). NEXT reads the matching one to decide which way
    /// the exit-sign branch should go when STEP wasn't a constant at
    /// compile time.
    for_step_sign_slots: usize,
    /// Number of int-FOR counter slots allocated. Each is 2 bytes,
    /// emitted at the end of the binary as `FI_<n>`.
    for_int_slots: usize,
    /// Number of u8-FOR counter slots allocated. Each is 1 byte,
    /// emitted at the end of the binary as `FU_<n>`. Used when
    /// start/end fit `[0,255]` and the literal step exactly reaches
    /// the end value without wrapping.
    for_u8_slots: usize,
    /// 5-byte float slots holding the running `var * K` value for
    /// FORs whose body matches the loop-induction pattern. Emitted
    /// at the end of the binary as `FB_<n>`.
    for_induction_slots: usize,
    /// 2-byte ZP-pointer slots holding `&A[loop_var]` for FORs whose
    /// body matches the array-pointer-induction pattern. Emitted at
    /// the end of the binary as `AP_<n>`. Allocated through the
    /// shared ZP pool when there's room; otherwise BSS-resident.
    for_array_ptr_slots: usize,
    /// True iff at least one int-FOR loop was emitted — pulls in the
    /// 2-byte `__FOR_DIFF_LO`/`__FOR_DIFF_HI` shared scratch used by
    /// the signed-16-bit compare at NEXT.
    used_int_for: bool,
    /// Count equality sites that can share a subtraction.
    equality_tail_sites: HashMap<EqTailKey, usize>,
    /// Track whether we ever needed BOOL_TO_FAC, so we only emit the
    /// helper when something refers to it.
    used_bool_to_fac: bool,
    /// Track whether any GET was emitted, so the shared `__GET_NUM`
    /// helper subroutine is only included when needed.
    used_get_num: bool,
    /// Track whether anything ever needs to print a length-prefixed
    /// string (literals or string variables).
    used_str_print: bool,
    /// Track whether the int16-print fast path was used in any PRINT.
    /// Emits the shared `__PRINT_INT16` helper that absorbs
    /// GIVAYF + __PRINT_FAC into one JSR.
    used_print_int16: bool,
    /// Track whether `GET A$` is used; emits a 1-char heap slot that
    /// holds the latest keystroke and a small helper to fill it.
    used_get_str: bool,
    /// True iff a GET-like path needs the shared 2-byte `__GET_HEAP`
    /// buffer. `used_get_str` additionally emits the non-blocking
    /// helper; blocking KEYGET string sites fill the buffer inline.
    used_get_heap: bool,
    /// Whether any ON KEY statement needs keyboard polling.
    used_on_key: bool,
    /// ON KEY's GOSUB form owns the poll's existing JSR frame.
    used_on_key_gosub: bool,
    /// `ON ERROR` / `RESUME` / `ERROR n` appears anywhere in the
    /// program. Gates the per-line `__TSB_RESUME_NEXT` stamp, the
    /// `__TSB_ERROR` dispatcher, and the `__TSB_GOTO_LINE` table.
    used_on_error: bool,

    used_error_continuation: bool,

    used_rom_error_hook: bool,
    /// True when the program writes to `ER` or `EL`, i.e. the user
    /// is using them as ordinary BASIC v2 variable names rather
    /// than the error pseudo-vars. When set, both reads
    /// and writes route through a regular Float scalar slot.
    er_el_as_user_var: bool,
    /// `RESUME` (Same/Next) needs the runtime line-table walker.
    used_tsb_goto_line: bool,
    /// True once the shared `GOTO <expr>` line search has been emitted.
    cgoto_dispatch_emitted: bool,
    /// Track whether `CHR$(...)` was used in any PRINT/LET-string
    /// context, to emit the shared `__CHR_HEAP` slot.
    used_chr_heap: bool,
    /// True iff CHR$ landed in any string-expression context — emits
    /// the `__CHR_NEW` helper that allocates a fresh temp chunk
    /// from the string heap per call. (Replaces the static buffer
    /// to avoid CHR$(A)+CHR$(B) collisions.)
    used_chr_new: bool,
    /// Track whether `+` was used between strings; emits the heap +
    /// __STR_CONCAT helper.
    used_concat: bool,
    /// Whether string concatenation can append to its own left operand.
    concat_appends_in_place: bool,
    used_str_from_number: bool,
    used_str_left: bool,
    used_str_right: bool,
    used_str_mid: bool,
    /// True iff `ASC(MID$(...))` used the helper `__ASC_MID`.
    used_asc_mid: bool,
    /// True iff anything in the program needs the heap initialised at
    /// startup (any of: concat, STR$, LEFT$, RIGHT$, MID$).
    heap_init_needed: bool,
    /// True iff `VAL` was used; emits the shared __VAL_HELPER routine.
    used_val: bool,
    /// Whether VAL can receive a pointer into the string heap.
    used_val_heap: bool,
    /// True iff `NRM(s$)` was used as a function (distinct
    /// from the NRM statement). Emits `__NRM_HELPER` which parses
    /// the string with format auto-detection (hex if len < 8,
    /// binary if len ≥ 8, optional `$`/`%` prefix tolerated).
    used_nrm_helper: bool,
    /// True iff `USR` was used; emits the USR vector wrapper and makes
    /// startup initialise the BASIC-compatible vector to a safe RTS.
    used_usr: bool,
    /// True iff `A$(I) = ...` was emitted; pulls in the temporary
    /// pointer slot used to bridge value-eval and address-eval.
    used_array_let_str: bool,
    /// True iff a `Stmt::PokeFill` was emitted — pulls in the
    /// `__POKE_FILL` runtime helper plus its 4-byte pointer/count
    /// scratch (`__PFL_PTR`, `__PFL_CNT`, `__PFL_END`).
    used_poke_fill: bool,
    /// True iff any `INPUT` appears — emits the shared input buffer
    /// and `__INPUT_LINE` helper.
    used_input: bool,
    /// True iff any `INPUT` reads a string variable — pulls in the
    /// `__INPUT_COPY_TO_HEAP` helper alongside the buffer.
    used_input_str: bool,
    /// All DATA values across the whole program, in source order. Empty
    /// when the program has no DATA at all (skips data-block emission
    /// and pointer-init prelude entirely).
    data_values: Vec<ast::DataValue>,
    /// How the DATA pool is laid out. Picked once per program after
    /// `collect_data` runs: binary i16 when every value is a small
    /// integer and no string READ exists; binary MFLPT when every
    /// value is numeric (but some don't fit i16); ASCII-length-prefix
    /// otherwise. The binary forms skip the BASIC ROM VAL parser and
    /// fixed-advance the DATA pointer with a `CLC + ADC #N` pair.
    data_pool_layout: DataPoolLayout,
    /// Per-line DATA-pool offsets. Filled by `collect_data` for
    /// every line that contributes DATA values; consumed when
    /// emitting the pool to drop a `__DATA_LINE_<n>:` label so
    /// `RESET <line>` can point the DATA pointer there.
    data_line_offsets: Vec<(u16, usize)>,
    /// DATA intervals that numeric READ rejects, with their BASIC line numbers.
    data_bad: Vec<(usize, usize, u16)>,
    /// DATA items every READ rejects, with their BASIC line numbers.
    data_unreadable: Vec<(usize, u16)>,
    /// Whether a string READ checks for those items.
    used_read_str_chk: bool,
    compact_data_metadata: bool,
    compact_data_bad: Option<crate::compact_data_bad::CompactDataBad>,
    /// Whether numeric READ needs the invalid-DATA table and check.
    used_read_num: bool,
    /// Whether the program can observe DATA line numbers through DATLIN.
    datlin_track: bool,
    /// Whether a READ requires DATLIN updates and the line table.
    used_datlin: bool,
    /// Each unique STATIC array variable and its declared dimensions.
    /// Used to allocate `__ARR_<name>` slots at the end of the binary
    /// and to validate that index counts match. `DIM A(10)` records
    /// `[10]`, `DIM A(10, 5)` records `[10, 5]`. Arrays whose DIM
    /// expressions don't fold to literals go to `runtime_arrays`.
    arrays: HashMap<VarName, Vec<u16>>,
    /// Insertion order so array-block emission is deterministic.
    arrays_order: Vec<VarName>,
    /// Declared array bounds, separate from space allocated for auto-DIM after CLR.
    array_declared_dims: HashMap<VarName, Vec<u16>>,
    /// Arrays whose DIM expressions aren't literal at compile time —
    /// the dim sizes get evaluated and stored in per-array descriptor
    /// slots when the program reaches the DIM statement, and a chunk
    /// is bump-allocated from the runtime array region (which grows
    /// downward from MEMSIZ). The descriptor holds the base pointer
    /// and per-dim max-index; access goes through them.
    runtime_arrays: HashMap<VarName, Vec<Expr>>,
    /// Stable iteration order for runtime arrays.
    runtime_arrays_order: Vec<VarName>,
    /// True iff any runtime DIM was emitted. Pulls in the
    /// `__ARR_HEAP_TOP` allocator slot, the `__DIM_ALLOC` helper, and
    /// changes the string-heap GC margin check to use the array-heap
    /// floor instead of MEMSIZ.
    used_runtime_dim: bool,
    /// Whether program writes can lower MEMSIZ below the runtime heap.
    memsiz_may_be_lowered: bool,
    /// Whether the program reads BASIC's FRETOP pointer.
    fretop_observable: bool,
    /// True iff any 2-D array reference was emitted; pulls in the
    /// `__MD_TMP_I` and `__MD_TMP_J` 5-byte FAC-stash slots used while
    /// computing the linear element index.
    used_md_array: bool,
    /// True iff any `SPC(...)` (or `TAB(...)`, since TAB tail-calls SPC)
    /// was emitted — pulls in the shared `__SPC` helper.
    used_spc: bool,
    /// True iff any `TAB(...)` was emitted — pulls in `__TAB` on top of
    /// `__SPC`.
    used_tab: bool,
    /// True iff any `PRINT TAB(<expr>)` site emits `JSR __TAB_FAC` —
    /// pulls in the combined FAC_BYTE+TAX+TAB helper.
    used_tab_fac: bool,
    /// True iff any `PRINT SPC(<expr>)` site emits `JSR __SPC_FAC`.
    used_spc_fac: bool,
    /// The first DEF FN for each name, with its parameter and body.
    def_fns: HashMap<FnName, DefFnInfo>,
    def_fns_order: Vec<FnName>,

    poisoned_fns: HashMap<FnName, u8>,
    /// Every `DEF FN` statement in the module, in source order, including repeat definitions of
    /// one name.
    all_def_fns: Vec<(FnName, DefFnInfo)>,
    /// Names with more than one `DEF FN`.
    dispatched_fns: HashSet<FnName>,
    /// Dispatched bodies registered while walking the program, as `(label, param, body)`.
    dispatched_bodies: Vec<(String, FnName, VarName, Expr)>,
    /// Per-name counter behind `dispatched_bodies`' label numbering.
    dispatched_seq: HashMap<FnName, usize>,
    /// Function names that need a dispatch trampoline.
    used_fn_dispatch: HashSet<FnName>,
    /// Whether a call can reach the undefined-function trap.
    used_undef_fn: bool,
    /// FN names whose body can re-enter itself, directly or through another FN.
    recursive_fns: HashSet<FnName>,

    used_fn_oom: bool,
    /// True iff any array reference emitted a bounds check. Pulls in
    /// the shared `__BAD_SUBSCRIPT` trap helper and its message string.
    used_bad_subscript: bool,
    /// True iff any bounds check can reach the ?ILLEGAL QUANTITY trap (negative or >32767
    /// subscript).
    used_illegal_qty: bool,
    /// True iff any READ emitted the end-of-pool check.
    used_data_chk: bool,
    /// Destination buffer for relocated DATA reads.
    data_relocate: Option<DataBuf>,
    /// Whether the DATA pool is relocated.
    data_relocated: bool,
    /// Bytes in the DATA pool.
    data_pool_len: usize,
    /// `__READ_STR_COPY` copies a buffered text item onto the heap.
    used_read_str_copy: bool,
    read_targets: usize,
    /// Some READ target is a float or a string, which take tagged items through FAC.
    read_needs_fac: bool,
    /// Some READ advanced the DATA cursor through `__DATA_ADVANCE`.
    used_data_advance: bool,
    /// True iff any orphan NEXT can find the runtime FOR stack empty.
    used_next_no_for: bool,
    /// True iff a runtime FOR-stack push or a GOSUB emitted a depth check.
    used_for_oom: bool,
    /// True iff any RETURN emitted the GOSUB-depth check.
    used_ret_chk: bool,
    /// True iff the program contains a `GOSUB` (including `ON x GOSUB`), which is what decides
    /// whether `__GOSUB_DEPTH` exists.
    uses_gosub: bool,
    /// True iff a GOSUB site emitted `JSR __GOSUB_CHK`.
    used_gosub_chk: bool,
    /// True iff an `ON n GOSUB` table calls through `__JMP22` (`JMP ($22)`).
    used_jmp22: bool,
    /// Use tagged binary integers when they save space.
    data_ints_tagged: bool,
    /// Items of a tagged pool that keep their text anyway (Speed: DATA lines with text in them).
    data_tags_kept_text: Vec<bool>,
    /// True iff a numeric READ enters through `__READ_TAGGED`.
    used_read_tagged: bool,
    /// True iff a string READ writes a tagged integer's digits through `__TAG_TEXT`.
    used_tag_text: bool,
    /// The entry `__READ_TAGGED` hands a text item to.
    read_tagged_text_entry: &'static str,
    /// Whether digit reads repay the helper size.
    read_digits: bool,
    /// Whether numeric READ needs the digit helper.
    used_read_digits: bool,
    /// An integer READ target takes digit items straight from LINNUM, without FAC.
    used_read_digits_int: bool,
    /// An integer READ target takes tagged items without FAC.
    used_read_tagged_int: bool,
    /// The integer READ entry an integer array element READ goes through, when one does.
    read_arr_int_entry: Option<&'static str>,
    /// True iff `VAL` enters through `__VAL_DIGITS`, the same shortcut in front of FIN.
    used_val_digits: bool,
    /// Whether GOSUB and RETURN checks are proved unnecessary.
    gosub_depth_free: bool,
    /// True iff a runtime FOR-stack push emitted `JSR __FOR_BYTES_CHK`.
    used_for_bytes_chk: bool,
    /// True iff a static-tier `FOR` emitted `JSR __FOR_DISCARD`.
    used_for_discard: bool,
    /// True iff a runtime `RETURN` emitted `JSR __FOR_WALK_MARK`.
    used_for_walk_mark: bool,
    /// Page-1 floors for which a shared GOSUB-marker push helper (`__FOR_MARK_<floor>`) has to be emitted.
    for_mark_floors: std::collections::BTreeSet<u8>,
    /// Table identifiers and targets for ON GOTO.
    on_tables: Vec<(usize, Vec<String>)>,
    /// GOSUB depth that raises OUT OF MEMORY.
    gosub_depth_limit: u8,

    page1_stmt_check: bool,
    /// Runtime FOR-stack size shared by allocation and bounds checks.
    for_stack_bound: ForStackBound,
    /// Variable IDs pushed onto the runtime FOR-stack.
    for_stack_pushed_vars: HashSet<u8>,
    /// Whether the program reads or writes CURLIN.
    curlin_observable: bool,
    /// True iff `emit_bounds_check` (the shared 7-byte JSR variant)
    /// fired anywhere. Pulls in the `__BNDS_CHECK` helper.
    used_bnds_check: bool,
    /// True iff any code path reads a Float array element via the
    /// 3-instruction `LDA $FD; LDY $FE; JSR MOVFM` pattern. Pulls in
    /// the `__LD_ARR` stub so each call site shrinks to a 3-byte JSR.
    used_ld_arr: bool,
    /// Same for stores: `LDX $FD; LDY $FE; JSR MOVMF` becomes
    /// `JSR __ST_ARR`.
    used_st_arr: bool,
    /// True iff the FAC-stash-to-T0 stub fired anywhere. T0 is the
    /// outermost temp slot in `emit_binop`/`emit_compare` and so is
    /// hit by every non-trivial binary op — stubbing it shrinks each
    /// call from 7 bytes to 3.
    used_st_t0: bool,
    /// Array indices and addresses use byte FOR counters as integer operands.
    index_context: std::rc::Rc<std::cell::Cell<bool>>,
    /// `__FAC_TO_ARG` and the ARG-operand entries a binary op used, by op.
    used_fac_to_arg: bool,
    used_arg_ops: Vec<BinOp>,
    /// Same idea for the four float-arithmetic ops with T0 as memory
    /// operand. Each used_op_t0 flag pulls in its own stub.
    used_fadd_t0: bool,
    used_fsub_t0: bool,
    used_fcmp_t0: bool,
    used_fmult_t0: bool,
    used_fdiv_t0: bool,
    /// Float-var load/store usage counts (separate buckets so we can
    /// emit one stub only when it actually beats the inline 7-byte
    /// LDA/LDY/JSR sequence). Filled by `count_var_helpers` before
    /// codegen runs.
    float_var_loads: HashMap<VarName, u32>,
    float_var_stores: HashMap<VarName, u32>,
    /// Same shape but for `%`-typed scalars: how many times the int
    /// var is read into FAC (via GIVAYF). Drives a per-var int-load
    /// stub so promoted vars don't pay an inline 9-byte sequence
    /// at every read site.
    int_var_loads: HashMap<VarName, u32>,
    /// Loop-weighted access counts for `%`-typed scalars, used only to
    /// rank zero-page promotion candidates: a read on a loop-hot line
    /// counts `ZP_LOOP_WEIGHT`×, so hot inner-loop variables win the
    /// scarce pool over cold ones even with fewer source reference
    /// sites. Distinct from `int_var_loads` (which drives stub
    /// emission, where loop-weighting would be counterproductive).
    int_var_zp_hotness: HashMap<VarName, u32>,
    /// Per-(var, op) usage counts for binops where a Var becomes the
    /// memory operand of FADD/FSUB/FMULT/FDIV — bypassing the
    /// ST_T0/LD/FADD_T0 dance entirely. Filled alongside the load/
    /// store counts. Op key is one of Add/Sub/Mul/Div.
    float_var_op_uses: HashMap<(VarName, BinOp), u32>,
    /// Per-dim BNDS_CHECK stub uses. Each unique dim value referenced
    /// by an array bounds check gets its own `__BNDS_<dim>` stub at
    /// the end of the binary; the call site is a 3-byte JSR. Filled
    /// during emission, drained at finish().
    bnds_stub_uses: HashMap<u16, u32>,
    /// Bounds-check stubs with the state byte and both possible array bounds.
    bnds_state_stubs: std::collections::BTreeMap<String, (String, u16, u16)>,
    /// Per-(dim_label) stub usage for runtime-dimensioned arrays.
    /// `__BNDS_RT_<dim_label>` does the sign check + 16-bit compare
    /// against the dim slot, trapping to `__BAD_SUBSCRIPT` when the
    /// index is out of range. Each call site is a 3-byte JSR.
    bnds_rt_stub_uses: HashMap<String, u32>,
    /// True iff any string compare was emitted; pulls in the shared
    /// `__STRCMP` helper that walks the pointer pair in
    /// STR_OP_LHS/RHS and returns a signum byte in .A.
    used_strcmp: bool,
    /// True iff any int-array element store fires; pulls in the shared `__ST_ARR_INT` helper
    /// that does `JSR __AYINT; <store 2 bytes via ARRAY_ADDR>`.
    used_st_arr_int: bool,
    /// Same idea but for numeric-literal mem operands (`X + 1`,
    /// `Y * 2`). Key is the f64's bit pattern so different `1.0`
    /// occurrences merge. The literal goes in the float pool the
    /// usual way; the stub label derives from the pool label.
    float_const_op_uses: HashMap<(u64, BinOp), u32>,
    /// True iff any AND/OR was emitted — pulls in the 2-byte
    /// `__LOGIC_LO`/`__LOGIC_HI` scratch used to stash one operand's
    /// integer truncation across the second operand's evaluation.
    used_logic: bool,
    /// Nesting depth of the multi-dimensional index scratch.
    md_depth: usize,
    /// Maximum number of simultaneous multidimensional index scratch pairs.
    md_max_depth: usize,
    /// Nesting depth of the AND/OR/EXOR scratch.
    logic_depth: usize,
    /// High-water mark of `logic_depth`, i.e. how many scratch pairs the BSS has to define.
    logic_max_depth: usize,
    /// Whether byte boolean operations need scratch storage.
    used_logic_byte: bool,
    /// High-water mark of `logic_depth` *as seen by the byte lowering*, i.e. how many
    /// `__LOGIC_B` cells the BSS has to define.
    logic_byte_max_depth: usize,
    /// Whether signed 16-bit conversion with BASIC range checks is needed.
    used_ayint: bool,
    /// Whether integer stores need ROUND before AYINT.
    used_ayint_rnd: bool,
    /// Whether AND and OR need rounding before AYINT.
    used_ayint_psh: bool,
    /// Whether internal signed 16-bit conversion without range checks is needed.
    used_fac_to_int16: bool,
    /// Whether unsigned 16-bit values need conversion to FAC.
    used_givayf_u16: bool,
    /// Track whether the non-trapping FAC → i16 helper was used.
    /// Pre-checks the FAC exponent so values that would trip
    /// FACWORD's overflow trap stash 0 in LINNUM instead. Used by
    /// shadow-int sync at INPUT sites where the user's value isn't
    /// statically bounded — moving an existing trap from
    /// "next AND/POKE/CHR$ read" to "INPUT itself" would change
    /// program semantics, so we suppress the trap here and let the
    /// out-of-range value flow through with garbage in the high
    /// byte. Byte-context reads only consult the low byte; other
    /// reads hit the FAC fall-back and re-trap there.
    used_fac_to_int16_notrap: bool,
    /// True iff the int-island MUL helper `__MUL16` was emitted —
    /// pulls in the ~35-byte unsigned 16x16→16 multiplication
    /// routine. Used by `try_emit_int16_eval_addsub` for general
    /// `Mul` nodes that aren't power-of-two.
    used_mul16: bool,
    /// True iff the trapping signed multiply `__MUL16C` was emitted.
    used_mul16c: bool,
    /// True iff the signed int-island DIV helper `__DIV16` was
    /// emitted. Implements floor-division on signed i16 with a
    /// `?DIVISION BY ZERO` trap. Both DIV(a,b) and MOD(a,b) on
    /// int-island leaf operands route through this single helper —
    /// after the call, NUM ($14/$15) holds the floor quotient and
    /// `__DIV16_REM` holds the floor remainder (sign of divisor).
    used_div16: bool,
    /// True iff `x / 2^k` used the exponent helper `__FDIV2K`.
    used_fdiv2k: bool,
    /// True iff `x * 2^k` used the exponent helper `__FMUL2K`.
    used_fmul2k: bool,
    /// True iff `2^n` used the helper `__POW2`.
    used_pow2: bool,
    /// True iff `2^n` used its entry `__POW2_FAC`, which takes n in FAC.
    used_pow2_fac: bool,
    /// True iff RND used the speed profile's `__RND_POS`.
    used_fast_rnd: bool,
    /// True iff RND used its entry `__RND`, which takes the argument in FAC.
    used_fast_rnd_arg: bool,
    /// True iff the small-constant MUL strength-reduction lowered a
    /// `Var * K` (K ∈ {3, 5, 6, 7, 9, 10, 12, ...}) into a shift+add
    /// chain — pulls in the 2-byte BSS scratch `__SMUL_TMP` used to
    /// stash the pre-shift value when the plan needs to add or
    /// subtract `var` back after shifting.
    used_smul_tmp: bool,
    used_hardcopy: bool,
    /// Whether TI needs its read helper.
    used_read_ti: bool,
    /// Whether TI$ needs its read helper and string slot.
    used_read_ti_str: bool,

    used_stop: bool,
    /// A reached bare `CONT` needs the shared `__HANG` spin.
    used_hang: bool,
    /// Last array address computed and currently held in
    /// ARRAY_ADDR_LO/HI ($FD/$FE). When a subsequent array reference
    /// requests the same name + indices, we skip the recomputation.
    /// Cleared at every statement boundary and at any operation known
    /// to clobber $FD/$FE (string-print, LEN, ASC, concat helpers).
    last_array_addr: Option<(VarName, Vec<Expr>)>,
    /// Active rebased PEEK window: `(base variable, bottom displacement)`.
    peek_rebase: Option<(VarName, i32)>,
    /// The integer island may read ASC, LEN and u16 literals while it evaluates for FAC.
    island_for_fac: bool,
    /// Expressions whose value is definitely still resident in FAC1.
    /// This is a tiny local CSE/liveness cache: helpers that consume or
    /// overwrite FAC clear it, while MOVMF-style stores can add aliases
    /// such as `LET A = expr` -> FAC contains both `expr` and `A`.
    fac_cache: Vec<Expr>,
    /// Runtime-DIM arrays whose `__ARR_<X>_BASE` pointer has already
    /// been guarded against the BSS-zero "DIM not yet run" trap on
    /// every path that can reach the current statement. Each access
    /// emits the OR-test + trap once per epoch and adds the var; later
    /// accesses skip the guard. Cleared at branch-target lines (other
    /// paths may have skipped the DIM), at \`CLR\` / \`RUN\` (those
    /// reset \`__ARR_<X>_BASE\` to zero), and on entry into IF/THEN
    /// bodies whose statements run conditionally.
    runtime_array_base_validated: HashSet<VarName>,
    /// Statically-allocated arrays that a `CLR`/`RUN` has un-DIMmed and that no later `DIM` has
    /// re-armed, on every path that reaches the current emission point.
    static_arrays_undimmed: HashSet<VarName>,
    /// Possible static array states at each statement with known control flow.
    array_states: Option<ArrayStateInfo>,
    /// Static arrays the `DIM` statement being emitted has declared so far.
    arrays_dimmed_in_stmt: HashSet<VarName>,

    redim_traps: HashSet<(u16, VarName)>,
    /// Arrays whose auto-DIM the ROM can never hold: every reference raises ?OUT OF MEMORY.
    oom_arrays: HashSet<VarName>,
    /// Runtime-DIM arrays whose `__ARR_<X>_BASE` lives in zero-page —
    /// the EQU directive at the top of the binary points the label
    /// at a 2-byte ZP slot, so the per-access \`ADC __ARR_<X>_BASE\`
    /// uses zp addressing automatically (1 byte shorter, 1 cycle
    /// faster) and the BSS slot in \`__VARS_START..__VARS_END\` is
    /// skipped. The set is also our gate for whether to skip BSS
    /// emission for that array's base.
    runtime_array_base_zp: HashSet<VarName>,
    /// True iff any OPEN was emitted — pulls in three byte slots
    /// `__OPEN_F/D/S` used to stage SETLFS arguments across the
    /// per-arg evaluations.
    used_open: bool,
    /// True iff a `PRINT#` or `CMD` reached the CHKOUT-with-error-check helper.
    used_chkout_check: bool,
    /// True iff a `GET#` or `INPUT#` reached the CHKIN-with-error-check helper.
    used_chkin_check: bool,
    /// True iff any INPUT# was emitted — pulls in the CHRIN-based
    /// `__INPUT_LINE_FILE` helper alongside the existing INPUT_BUF
    /// machinery.
    used_input_file: bool,
    /// True iff `LET TI$ = ...` was emitted — pulls in the helper that
    /// parses the HHMMSS source string and stamps the jiffy counter.
    used_set_ti: bool,
    /// True iff `PRINT A, B`-style comma was emitted — pulls in the
    /// `__PRINT_COMMA` helper that pads to BASIC v2's 10-column zones.
    used_print_comma: bool,
    /// True iff multi-var INPUT was emitted — pulls in `__EXTRACT_FIELD`
    /// (comma-aware field cutter) and the `__INPUT_POS` cursor + the
    /// 80-byte `__FIELD_BUF` length-prefixed scratch.
    used_input_field: bool,

    used_input_redo: bool,

    used_input_extra: bool,
    /// True iff anything emitted a "must fit in a byte" check — pulls
    /// in the shared `__CHK_BYTE` helper that traps to ?ILLEGAL QUANTITY
    /// when LINNUM_HI is non-zero (i.e., the value just FACWORDed is
    /// >= 256). Used by CHR$, PRINT CHR$, POKE value, WAIT mask/eor.
    used_chk_byte: bool,
    /// True iff the combined `__FAC_BYTE` helper is referenced — does
    /// `FACWORD; CHK_BYTE; LDA LINNUM_LO` (returns the byte in .A).
    /// Replaces the 8-byte triplet at every POKE-value, CharOut, SPC,
    /// TAB, CHR$, etc. site with a 3-byte JSR.
    used_fac_byte: bool,
    /// True iff the no-check FAC-to-byte helper `__FAC_BYTE_OK` is
    /// referenced — used at sites where range facts prove the value
    /// is already in `0..=255`, so the high-byte error check inside
    /// `__FAC_BYTE` would be dead code. Body is just `FACWORD; LDA
    /// LINNUM_LO; RTS` (6 bytes vs ~12 for `__FAC_BYTE`). Distinct
    /// helper rather than inline so the call site stays a 3-byte
    /// JSR — keeps peephole factoring (PH113/PH301) alive on the
    /// surrounding load+convert pair.
    used_fac_byte_ok: bool,
    /// True iff `JOY(n)` was emitted; pulls in the active-low
    /// joystick normaliser helper and its lookup table.
    used_joy: bool,
    /// True iff `PAUSE n` was emitted; pulls in a one-byte jiffy
    /// latch used by the delay loop.
    used_pause: bool,
    /// True iff `PAUSE msg$, n` (the optional leading message form)
    /// was emitted — pulls in the `__PAUSE_MSG_LEN` data byte.
    used_pause_msg: bool,
    /// True iff a screen rectangle helper (FCHR/FCOL/FILL/INV)
    /// was referenced. Pulls in shared rectangle scratch slots.
    used_tsb_rect: bool,
    used_tsb_rect_fill: bool,
    used_tsb_rect_inv: bool,
    used_tsb_rect_move: bool,
    used_tsb_rect_scroll: bool,
    /// True iff `HIRES` was emitted — pulls in the bitmap clear /
    /// mode-set helper plus the default colour-pair pattern.
    used_hires: bool,
    /// True iff a single-pixel hires plot was emitted. Pulls in
    /// `__DRAW`, the per-row bitmap-base lookup table, and the
    /// bit-mask LUT.
    used_hires_draw: bool,
    /// True iff `LINE x1,y1,x2,y2` was emitted — pulls in the
    /// Bresenham helper which depends on `__DRAW`.
    used_hires_line: bool,
    /// True iff `REC x,y,w,h` was emitted — pulls in `__REC` which
    /// chains four `__LINE` calls for the rectangle outline.
    used_hires_rec: bool,
    /// True iff `BLOCK x1,y1,x2,y2` was emitted — pulls in
    /// `__BLOCK` which fills the rectangle with horizontal
    /// `__LINE` calls.
    used_hires_block: bool,
    used_hires_circle: bool,
    used_hires_circle_arc: bool,
    used_hires_mod: bool,
    used_hires_dup: bool,
    used_hires_char: bool,
    used_hires_text: bool,
    used_hires_cursor: bool,
    used_hires_rot: bool,
    used_hires_draw_str: bool,
    used_hires_paint: bool,
    used_hires_angl: bool,
    used_tsb_tmp: bool,
    used_tsb_sid: bool,
    used_music_play: bool,
    used_flash: bool,
    used_bflash: bool,
    /// Gate for the `__INT_TO_HEX` helper that backs `$$<expr>`.
    used_int_to_hex: bool,
    /// Gate for the `__INT_TO_BIN` helper that backs `%%<expr>`.
    used_int_to_bin: bool,
    /// True iff FLASH or BFLASH is used anywhere — gates the
    /// `__TSB_IRQ_INSTALL` prelude call and the `__TSB_IRQ_HANDLER`
    /// definition. The handler bumps `$C516` (zaeirq) every IRQ
    /// (~60 Hz) and toggles `$C5C7` bit 7 every FLASH tick. Programs
    /// use these addresses as polling targets; without
    /// them, `WAIT $C5C7,...` and `UNTIL PEEK($C516)>30` loops
    /// hang forever.
    used_tsb_irq: bool,
    used_fetch: bool,
    used_key_table: bool,
    used_mem_copy: bool,
    used_mem_fill: bool,
    used_scr_snapshot: bool,
    /// True iff sprite register helpers/scratch are needed for MMOB,
    /// MOB SET, RLOCMOB, or CHECK's bit-mask table.
    used_tsb_sprite: bool,
    /// True iff LOW COL / HI COL state slots are referenced.
    used_tsb_lowcol: bool,
    /// True iff `MULTI ON` appears anywhere in the program — gates
    /// the runtime MULTI flag and the `__DRAW_MC` 2-bit pixel path.
    used_tsb_multi: bool,
    /// True iff bare `MEM` appears anywhere — gates emission of
    /// the `__MEM_INIT` helper (chars-to-$E000 copy + VIC bank /
    /// $D018 / KERNAL $0288 reconfigure) and switches CSET 0/1
    /// to the MEM-mode XOR'd $D018 values.
    used_mem_mode: bool,
    /// True iff any drawing command takes (or could take) a mode
    /// argument. CHAR/TEXT always set this since they expose mode;
    /// other commands set it when the parser captured a trailing
    /// mode arg. Gates the per-op dispatch in __DRAW / __DRAW_MC
    /// so simple HIRES programs keep the lean set-only path.
    used_draw_mode: bool,
    /// True iff DETECT/CHECK state is used.
    used_tsb_detect: bool,
    /// string helpers.
    used_str_dup: bool,
    used_str_insert: bool,
    used_inst: bool,
    /// `INSERT box$, …` with a non-literal box pattern — emits the
    /// `__INSERT_BOX_PARSE` helper + `__INSERT_BOX_BUF`/`__INSERT_BOX_TMP`.
    used_insert_box_runtime: bool,
    /// Need the TSB ?BAD MODE (error 32) printer. ROM messages stop at 30.
    used_tsb_bad_mode: bool,
    /// `USE "…###…", v` formatted-PRINT field — emits the
    /// mask buffer, field descriptors, and
    /// __USE_LOAD / __USE_DESC / __USE_FLD / __USE_SHOW.
    used_use_format: bool,
    /// `USE` with a string-expression control string. Adds the runtime mask scanner.
    used_use_dyn: bool,
    /// `RESET <expr>` needs the runtime DATA-line table and its search.
    used_reset_find: bool,
    /// Both sides of a string compare rebuild the same slot. Pulls in __STR_SNAP.
    used_str_snap: bool,
    /// TSB dialect: boot charset and colours match TSB, not a stock C64.
    tsb_target: bool,
    /// Longest `USE` control string in the module. Size of __USE_BUF.
    use_buf_len: u8,
    /// `MOB SET …,speed` writes or `MMOB`/`RLOCMOB` glide reads —
    /// emits `__MOB_SPEED` (8-byte per-sprite delay table) and the
    /// `__MMOB_GLIDE` helper.
    used_mmob_glide: bool,
    /// String variables that may be involved in pointer-style source
    /// expressions (`A$ = B$`, `A$ = N$(I)`, `N$(I) = B$`). The current
    /// owner-backed LET path copies values, but this set still keeps
    /// the BSS-buffer string optimization conservative around statement
    /// forms that can observe or mutate the same string slot.
    shared_strings: HashSet<VarName>,
    /// String vars whose maximum length is small and statically known,
    /// not aliased, and never written by INPUT/GET/READ. We give each
    /// one a dedicated BSS buffer; LET copies into the buffer and the
    /// var pointer (initialised once at startup) always points at it,
    /// so multi-var loops don't accumulate orphaned heap chunks.
    /// Map value is the maximum payload length (1..=255).
    bss_str_vars: HashMap<VarName, u8>,
    /// True iff any LetStr emitted the BSS-buffer path — pulls in the
    /// `__SBUF_COPY` helper plus its scratch slots.
    used_sbuf_copy: bool,
    /// True iff persistent string assignment copies into an
    /// owner-backed heap chunk. Pulls in `__STR_ASSIGN_OWNED`.
    used_str_assign_owned: bool,
    /// True iff any string LET emits LASTVAR-rewind machinery. Pulls
    /// in the 4 BSS bytes that track the most-recently-stored string
    /// var (`__LAST_STR_VAR_LO/HI` + `__LAST_STR_PTR_LO/HI`) and the
    /// init that zeros them at startup. When the LET's dest is the
    /// same var as the previous string write, rewind
    /// `__HEAP_PTR` to that var's chunk start, so the new
    /// allocation overwrites the now-stale chunk instead of leaving
    /// it as heap garbage.
    used_lastvar_str: bool,
    /// `__ARR_APPEND_PRE`/`__ARR_APPEND_POST`: `A$(I)=A$(I)+X$` grows the element in place.
    used_arr_append: bool,

    used_lvc_helper: bool,
    used_lvu_helper: bool,
    /// Share LASTVAR checks and updates when their total size is smaller.
    lvc_out_of_line: bool,
    lvu_out_of_line: bool,
    /// Save the result directly from live A/Y instead of rereading the string slot in the helper.
    lvu_capture_pointer: bool,
    /// True iff anything triggers garbage collection (FRE call, or an
    /// owner-backed string assignment). Pulls in `__GC_RUN`, a compact
    /// linear collector that follows each chunk's owner back-pointer
    /// instead of scanning every possible BASIC string slot.
    used_gc: bool,
    /// True iff the program calls `FRE()`.
    used_fre: bool,
    /// True iff the program contains a `RUN` statement. Pulls in the
    /// `__RUN_RESTART` helper which resets variables, arrays, heap
    /// and DATA pointer back to startup state and jumps to the first
    /// line. Also pulls in `__MEMZERO` for clearing arrays.
    used_run: bool,
    /// True iff the prelude snapshots the SYS-entry stack pointer into
    /// `__SAVED_SP`. `RUN` and `END` both roll the stack back to it so
    /// they leave a clean frame for the BASIC-side return.
    used_saved_sp: bool,
    /// True iff any `CLR` statement was emitted. Pulls in the
    /// `__STATE_RESET` helper (also reused by RUN's restart path).
    used_state_reset: bool,
    /// True iff any FOR loop's STEP was dynamic (didn't fold to a
    /// literal). Pulls in the per-FOR sign-byte slot allocations.
    used_dyn_step: bool,
    /// True iff any integer-array element was read in expression
    /// context. Pulls in the `__ARRAY_INT_TMP` 1-byte slot used to
    /// stash the lo byte while the hi byte is loaded for GIVAYF.
    used_array_int_tmp: bool,
    /// True iff a call site used the int16 SGN helper.
    used_sgn_int16: bool,
    /// True iff `__HEAP_INIT` emitted a string-array initialiser. Pulls
    /// in the `__FILL_EMPTY_STR` helper which fills a 2-byte slot run
    /// with &__EMPTY_STR.
    used_fill_empty_str: bool,
    /// Line number of the program's first line — `__RUN_RESTART` JMPs
    /// to `L<first_line>` after re-initialising state. Captured during
    /// `run()`; 0 if the module has no lines (in which case `RUN`
    /// itself is unreachable so the field is never read).
    first_line: u16,
    line_numbers: Vec<u16>,
    uses_rcomp: bool,
    /// Optimisation profile selected by the caller (CLI flag). Drives
    /// any size-vs-speed branch in codegen; pure win-win paths ignore
    /// it. Currently stored but not yet branched on — wired so future
    /// optimisations can read it without re-plumbing.
    #[allow(dead_code)]
    profile: Profile,
    /// `*=$XXXX` directive value emitted at the head of the assembly.
    /// Defaults to [`CODE_ORIGIN`]; the custom-start-address path
    /// overrides it after construction via [`emit_with_profile_at`].
    code_origin: u16,
    /// Float scalars that range analysis proved are always int16. In
    /// Speed profile we keep a 2-byte shadow slot beside the normal
    /// 5-byte BASIC float slot so int-island paths can read them
    /// without a FAC roundtrip while ordinary BASIC-visible reads still
    /// see the float slot.
    shadow_int_vars: HashMap<VarName, String>,
    /// Speculatively omitted float mirrors.
    omitted_float_slots: HashSet<VarName>,
    /// Float scalars that also keep a checked 16-bit copy in speed (see `CheckedShadow`).
    checked_shadows: HashMap<VarName, CheckedShadow>,
    /// Checked integer copies and the ranges proved by the active guard.
    cs_active: Vec<(VarName, crate::dataflow::IntRange)>,
    /// Times code generation consulted an active checked copy.
    cs_hits: std::cell::Cell<usize>,
    /// Set while `emit_let` emits the float store of a checked variable.
    cs_plain_let: bool,
    /// Lines of short loops, the only ones that read checked copies.
    cs_tight_lines: HashSet<u16>,
    /// The line of the statement being emitted.
    cs_line: u16,
    /// Checked variables whose float slot is written through `__CS_ST_<label>`.
    cs_store_stubs: Vec<VarName>,
    /// Checked variables that are also FOR variables.
    cs_for_vars: HashSet<VarName>,
    /// Open loops whose NEXT must mark checked copies stale.
    cs_dirty_loops: HashSet<String>,
    source_integer_vars: SourceIntegerVars,
    /// Final-IR execution counts prove every assignment to these scalars stays in i16.
    bounded_accumulators: HashSet<VarName>,
    /// Subset of `shadow_int_vars` whose value range needed u16 (not
    /// i16) to fit. The 2-byte storage is identical and ADC/SBC
    /// arithmetic works bit-pattern-wise either way, so most int-
    /// island consumers don't care. The flag exists for paths that
    /// DO interpret signedness — comparisons, FAC sync — so they
    /// can refuse to lower these vars or pick an unsigned helper.
    shadow_unsigned: HashSet<VarName>,
    /// Labels promoted to zero-page slots. Each entry maps a slot
    /// label (e.g., `__SI_V_A`) to its ZP base address. ZP-resident
    /// labels emit as `<label> = $XX` near the binary's start so
    /// every `LDA <label>` / `STA <label>` / `<label>+1` reference
    /// resolves to a 2-byte ZP instruction at assembly time —
    /// 1 byte and 1 cycle smaller than the absolute form.
    /// `__STATE_RESET` clears these byte-by-byte before main.
    zp_promotions: Vec<(String, u8, usize)>,
    /// String-heap cells moved to zero page, as (label, address of the low byte).
    zp_heap_cells: Vec<(&'static str, u8)>,
    /// Integer variables whose `V_<base>` slot was placed in zero
    /// page. `intern_var` skips appending these to `vars_order` so
    /// the absolute BSS slot isn't also emitted.
    zp_int_vars: HashSet<VarName>,
    /// Integer scalars whose complete write set is range-proved to
    /// fit in a single byte (256 distinct values inside [-128, 255]).
    /// These use a one-byte slot. The subset in `signed_byte_int_vars`
    /// can hold negative values and needs sign-extension on widening;
    /// vars in this set but NOT in the signed subset are pure
    /// unsigned u8 [0, 255] and widen with `LDA #$00`.
    u8_int_vars: HashSet<VarName>,
    /// Subset of `u8_int_vars` whose range includes negative values.
    /// Reading the high byte from these requires sign-extension
    /// (bit 7 of the byte → $00 or $FF) rather than the cheaper
    /// `LDA #$00` used for pure u8 vars.
    signed_byte_int_vars: HashSet<VarName>,
    /// Proven numeric bounds for signed variables stored in one byte.
    signed_byte_int_bounds: HashMap<VarName, (i32, i32)>,
    /// Names of all `__SXT_TMP_<n>` scratch slots used by the i16
    /// add/sub path to materialise the sign-extended hi byte of a
    /// signed-u8 var operand before the ADC/SBC chain. Each one
    /// gets a single-byte BSS reservation in the trailing data
    /// section. Cleared per compile run.
    signed_u8_sxt_scratches: HashSet<String>,
    /// Free zero-page bytes still available for promotion. Drained
    /// by `collect_shadow_ints`, `collect_zp_int_vars`, and the
    /// FOR-counter pre-pass; whichever order picks first wins.
    ///
    /// The pool is computed per-module from a feature scan in
    /// `compute_zp_pool` so we only claim addresses that are actually
    /// safe for THIS program. The "always-safe" core lives in BASIC-
    /// interpreter scratch we never touch ($02, $08-$0C, $13,
    /// $16-$21); everything else is conditionally added when the
    /// program demonstrably doesn't use the feature that owns it.
    zp_pool: Vec<u8>,
    /// Pool bytes handed out by `alloc_zp_word` / `alloc_zp_byte`,
    /// recorded so `emit_sys` can save/restore them under
    /// `--safe-sys-calls`. Append-only.
    zp_claimed: Vec<u8>,
    /// Zero-page pointer locations used when rewriting emitted operands.
    zp_plan: ZpPlan,
    /// Store the DATA cursor in BSS when SYS or USR can overwrite zero page.
    data_cursor_bss: bool,
    /// Zero-page allocation diagnostics.
    zp_pressure: ZpPressure,
    /// Shared CURLIN high byte, initialized once when all lines have the same value.
    curlin_hi_invariant: Option<u8>,
    /// Line number to write to CURLIN at the next statement that can raise an error.
    pending_curlin: Option<u16>,

    curlin_hi_marked: bool,
    /// A `GOSUB` on this line has returned and nothing has re-stamped CURLIN since, so `$3A`
    /// holds whatever high byte the subroutine left.
    curlin_clobbered_by_call: bool,
    /// Whether a statement or returning subroutine changed CURLIN's low byte.
    curlin_lo_dirty: bool,
    /// Line number to restore on entry to the current FOR body.
    for_top_curlin: Option<u16>,

    for_top_restamp_sites: HashSet<(usize, Vec<usize>)>,
    /// When true, every emitted `SYS` PHA-saves $FB-$FE and the bytes
    /// in `zp_claimed`, restoring them after the JSR.
    safe_sys_calls: bool,
    /// Omit error checks and line tracking unless the program uses error handlers.
    unchecked: bool,
    /// `--fast-float`: the speed profile's float code in every profile.
    fast_float: bool,
    /// Route each param-`SYS`'s return sequence through the shared `__SYS_TXT_OUT` subroutine instead of inlining it.
    sys_param_helper: bool,

    used_sys_txt_out: bool,
    /// Maximum SYS parameter text length after variable substitution.
    sys_txt_buf_len: usize,
    /// Maximum simultaneous lazy string descriptors in one SYS text.
    sys_string_slots: usize,
    /// Whether any site emitted `JSR __SYS_PB_VAL`, so `finish` knows to write the body.
    used_sys_pb_val: bool,

    sys_regs_helper: bool,

    used_sys_regs: bool,
    /// Variable bases the user declared as single-byte via REM hints.
    /// `collect_u8_int_vars` adds these to the u8 set without the
    /// usual range proof; an out-of-range write wraps at runtime, as
    /// it would under the source compiler.
    forced_byte_bases: std::collections::HashSet<String>,
    /// Variable bases the user asked to live in zero page via REM
    /// hints (Basic-Boss `=FAST`). `collect_zp_int_vars` promotes
    /// these ahead of the hotness-based ranking.
    forced_zp_bases: std::collections::HashSet<String>,
    /// `for_int_slots` IDs whose FI_<n> slot landed in zero page
    /// (populated by the FOR-counter pre-pass and consumed at
    /// `emit_for_int`).
    zp_int_for_assignments: HashMap<usize, u8>,
    /// `for_u8_slots` IDs whose FU_<n> slot landed in zero page.
    zp_u8_for_assignments: HashMap<usize, u8>,
    /// Counter identifiers tied to their FOR statements.
    planned_int_for_ids: HashMap<crate::cfg::StmtPath, usize>,
    planned_u8_for_ids: HashMap<crate::cfg::StmtPath, usize>,
    /// FOR-counter ZP slots handed out so far, available for reuse by a
    /// later FOR counter whose loop variable doesn't interfere with any
    /// current owner. A FOR loop always initialises its counter at loop
    /// entry before any read, so sharing a slot between non-overlapping
    /// loops is sound (no reliance on a default value left in the slot).
    /// Only FOR-counter slots live here — scalar / shadow slots aren't
    /// reused (they'd need a defined-before-use proof, not just
    /// liveness).
    zp_for_reuse_slots: Vec<ZpReuseSlot>,
    /// Hot Integer-var ZP slots available for sharing by a later hot
    /// Integer var that is both non-interfering and proven
    /// defined-before-use. Only the first few vars take a fresh pool
    /// byte; additional safe candidates alias one of these instead of
    /// falling back to BSS.
    zp_int_reuse_slots: Vec<ZpReuseSlot>,
    /// Cached IR analyses shared by all codegen decisions. Built once
    /// via the analysis registry so later codegen fast paths can query
    /// facts without running their own ad-hoc walks.
    analysis: CodegenAnalysis,
    /// FORs, GOSUBs and RETURNs that opt into the runtime FOR-stack.
    /// Empty for programs without an orphan NEXT.
    orphan_for_next: OrphanAnalysis,
    /// FOR frames captured at emit time, consumed in finish() to emit
    /// the per-FOR handler and dispatch table.
    runtime_for_frames: std::collections::HashMap<u8, ForFrame>,
    /// `top_label`s of FORs that pushed onto the runtime FOR-stack.
    /// Their static NEXT also pops the stack on exit so frames don't
    /// leak across re-entries.
    runtime_for_top_labels: HashSet<String>,
    /// CFG node/path for the statement currently being emitted. These
    /// are set by `emit_stmt_at_path`, including nested IF bodies, and
    /// let expression-level helpers read per-statement numeric facts.
    current_stmt_node: Option<usize>,
    current_stmt_path: Option<crate::cfg::StmtPath>,
}

#[derive(Clone)]
struct CodegenAnalysis {
    numeric_facts: crate::dataflow::NumericFactsResult,
    /// Flow-independent literal scalar bounds shared with IntPromote's FOR storage proof, including the uninitialised value zero.
    literal_for_bounds: HashMap<VarName, crate::dataflow::IntRange>,
    effects: crate::analysis::EffectSummaryResult,
    /// Variable interference graph (from `LiveVars`). Used by the
    /// FOR-counter ZP allocator to let counters whose loop variables
    /// are never simultaneously live share a single zero-page slot.
    interference: crate::dataflow::InterferenceGraph,
    /// Variables proven always-written-before-read (forward
    /// must-analysis). Only these may *share* a sole-storage ZP slot —
    /// a variable that can read its slot before writing it would
    /// otherwise observe a co-tenant's bytes instead of the default 0.
    defined_before_use: std::collections::HashSet<VarName>,
    /// Zero-page bytes accessed by the program through POKE, PEEK or WAIT.
    zp_reach: ZpProgramReach,
    /// Whether a loop prints numbers often enough to use fast helpers.
    prints_numbers_in_a_loop: bool,
    /// Each FOR loop's header and NEXT node with the float variables its statements write.
    loop_float_writes: Vec<(usize, usize, HashSet<VarName>)>,
    node_of_path: HashMap<crate::cfg::StmtPath, usize>,
    cfg: crate::cfg::Cfg,
}

impl CodegenAnalysis {
    fn from_module(module: &ir::Module) -> Self {
        let mut registry = crate::analysis::Registry::new();
        let numeric_facts = registry
            .get(module, &crate::dataflow::NumericFactAnalysis)
            .clone();
        let effects = registry
            .get(module, &crate::analysis::EffectSummaryAnalysis)
            .clone();
        let interference = registry
            .get(module, &crate::dataflow::VarInterference)
            .clone();
        let defined_before_use = registry
            .get(module, &crate::dataflow::DefinedBeforeUse)
            .clone();
        let cfg = registry.get(module, &crate::cfg::CfgBuild).clone();
        let zp_reach = scan_zp_program_reach(module, &cfg, &numeric_facts);
        let prints_numbers_in_a_loop = prints_numbers_in_a_loop(module, &cfg);
        let loops = registry.get(module, &crate::analysis::LoopAnalysis).clone();
        let loop_float_writes = loops
            .loops
            .iter()
            .map(|lp| {
                let writes = (lp.header..=lp.latch)
                    .filter_map(|n| effects.summary_for_node(n))
                    .flat_map(|e| e.writes.iter())
                    .filter_map(|w| match w {
                        crate::analysis::EffectRegion::ScalarFloat(v) => Some(v.clone()),
                        _ => None,
                    })
                    .collect();
                (lp.header, lp.latch, writes)
            })
            .collect();
        let node_of_path = cfg
            .nodes
            .iter()
            .enumerate()
            .map(|(id, node)| (node.stmt.clone(), id))
            .collect();
        Self {
            numeric_facts,
            literal_for_bounds: crate::passes::literal_scalar_i16_ranges(module),
            effects,
            interference,
            defined_before_use,
            zp_reach,
            prints_numbers_in_a_loop,
            loop_float_writes,
            node_of_path,
            cfg,
        }
    }

    /// Whether the innermost FOR loop around `path` leaves `var` alone.
    fn innermost_loop_keeps(&self, path: &crate::cfg::StmtPath, var: &VarName) -> bool {
        let Some(&node) = self.node_of_path.get(path) else {
            return false;
        };
        self.loop_float_writes
            .iter()
            .filter(|(header, latch, _)| *header < node && node < *latch)
            .max_by_key(|(header, ..)| *header)
            .is_some_and(|(.., writes)| !writes.contains(var))
    }

    fn for_expr_int_range(
        &self,
        path: &crate::cfg::StmtPath,
        expr: &Expr,
    ) -> Option<crate::dataflow::IntRange> {
        let local = self.numeric_facts.expr_int_range_before_path(path, expr);
        let global = match expr {
            Expr::Var(v) => self.literal_for_bounds.get(v).copied(),
            _ => None,
        };
        match (local, global) {
            (Some(a), Some(b)) => {
                let (lo, hi) = (a.min.max(b.min), a.max.min(b.max));
                (lo <= hi).then(|| crate::dataflow::IntRange::new(lo, hi))
            }
            (a, b) => a.or(b),
        }
    }
}

/// One reusable zero-page slot and the set of variables that share it.
/// A new variable may join iff it interferes with none of `vars`.
/// Used for two pools: FOR-counter slots (safe because a FOR always
/// writes its counter before the body reads it) and hot Integer-var
/// slots (safe only for variables proven defined-before-use).
#[derive(Debug, Clone)]
struct ZpReuseSlot {
    addr: u8,
    /// Slot width in bytes: 2 for an int slot, 1 for a u8 slot.
    size: u8,
    vars: Vec<VarName>,
}

/// Find an existing slot of the requested `size` that `var` can safely
/// reuse — i.e. one where every current owner is non-interfering with
/// `var`. Returns the index into `slots`, or `None` when `var` needs
/// its own slot. Pure (no `self`) so the decision is unit-testable in
/// isolation. Callers are responsible for any additional soundness
/// gate (e.g. defined-before-use) before offering a var to this pool.
fn find_reuse_slot(
    slots: &[ZpReuseSlot],
    size: u8,
    var: &VarName,
    interference: &crate::dataflow::InterferenceGraph,
) -> Option<usize> {
    slots.iter().position(|slot| {
        slot.size == size
            && slot
                .vars
                .iter()
                .all(|owner| !interference.interferes(owner, var))
    })
}

#[derive(Debug, Clone)]
struct DefFnInfo {
    param: VarName,
    body: Expr,
}

/// Possible runtime states of static arrays declared by DIM.
#[derive(Clone)]
struct ArrayStateInfo {
    index: HashMap<VarName, usize>,
    per_node: Vec<Vec<u8>>,
    refs: Vec<Vec<usize>>,
    /// Combined array states for code shared by several statements.
    any: Vec<u8>,
    /// Array state bytes: 0 absent, 1 implicit, 2 declared by DIM.
    labels: Vec<Option<String>>,
    /// Arrays whose creation must be recorded for later DIM checks.
    dim_tested: Vec<bool>,
}

/// Which bound a static array access checks.
#[derive(Clone, Copy, PartialEq, Eq)]
enum ArrayMode {
    Declared,
    Implicit,
    /// Either one, picked at run time.
    Either,
}

/// Checked 16-bit copy of a float scalar; byte 2 is zero while the copy is current.
#[derive(Clone)]
struct CheckedShadow {
    label: String,
    /// The copy holds 0..65535 rather than -32768..32767.
    unsigned: bool,
}

impl CheckedShadow {
    fn range(&self) -> crate::dataflow::IntRange {
        if self.unsigned {
            crate::dataflow::IntRange::new(0, 65535)
        } else {
            crate::dataflow::IntRange::i16()
        }
    }
}

/// Machine state shared by both versions of a guarded statement.
#[derive(Clone)]
struct CsState {
    fac_cache: Vec<Expr>,
    last_array_addr: Option<(VarName, Vec<Expr>)>,
    peek_rebase: Option<(VarName, i32)>,
    runtime_array_base_validated: HashSet<VarName>,
    static_arrays_undimmed: HashSet<VarName>,
    curlin_hi_marked: bool,
    curlin_clobbered_by_call: bool,
    curlin_lo_dirty: bool,
}

#[derive(Clone)]
enum ForFrame {
    /// FAC-based loop: counter, end, and step all live in MFLPT slots
    /// and the per-NEXT increment goes through FADD. Used for any loop
    /// whose start/end/step isn't a small integer literal.
    Float(FloatForFrame),
    /// Native 16-bit integer loop: counter is two ZP-style bytes,
    /// increment is CLC/ADC, exit-test is a signed 16-bit compare.
    /// V_var is synced from the int counter at every NEXT so the body
    /// can still read the loop variable as a float.
    Int(IntForFrame),
    /// 8-bit unsigned integer loop: counter is one byte, end-test is
    /// a single CMP, and literal STEP is applied with INC/DEC or
    /// ADC/SBC immediate. Picked when start/end fit in `[0, 255]`
    /// and the step lands exactly on END.
    U8(U8ForFrame),
    /// Unsigned 16-bit loop bounds used by POKE and PEEK addresses.
    U16(IntForFrame, u16),
}

/// Shorthand for the statement identity `for_next_runtime` keys its pairing on.
type ForNextStmtId = crate::for_next_runtime::StmtId;

/// What a single `NEXT` closed, as codegen decided it.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
enum NextBinding {
    /// No NEXT binding recorded.
    #[default]
    Unset,
    /// Closed the loop whose top label this is, with an inline tail.
    Frame(String),
    /// Stack underflow, re-emitted a retired loop's tail (the `IF cond THEN NEXT` shared-tail
    /// idiom).
    SharedTail(String),
    /// Stack underflow with nothing to re-emit: `?NEXT WITHOUT FOR`.
    NoFor,
}

#[derive(Clone, Debug)]
struct StructuredLoopFrame {
    kind: StructuredLoopKind,
    top_label: String,
    exit_label: String,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StructuredLoopKind {
    Repeat,
    Loop,
}

#[derive(Clone, Debug)]
struct DoFrame {
    else_label: String,
    end_label: String,
    seen_else: bool,
}

#[derive(Clone)]
struct FloatForFrame {
    var: VarName,
    end_slot_label: String,
    /// The end, when it is an integer literal.
    end_literal: Option<i32>,
    step_loc: StepLoc,
    top_label: String,
    exit_label: String,
    induction: Option<InductionFrame>,
    array_pointers: Vec<ArrayPtrFrame>,
}

/// Per-FOR strength-reduction state for `var * K` (constant K).
/// `slot_label` names a 5-byte float slot that holds the running
/// value of `var * K`: initialised at the FOR header, advanced by
/// `step * K` inside NEXT. `k_value` is the literal multiplier and
/// is matched against `Bin(Mul, Var(var), Number(k))` /
/// `Bin(Mul, Number(k), Var(var))` shapes during expression
/// emission so codegen can swap the multiply for a single MOVFM
/// from the slot.
#[derive(Clone, Debug)]
struct InductionFrame {
    k_value: f64,
    slot_label: String,
}

/// Ascending byte copy and the counter value after the loop.
#[derive(Clone, Debug)]
struct CopyLoop {
    var: VarName,
    src: u16,
    dst: u16,
    len: u32,
    exit: f64,
    /// The FOR ends its line and the POKE and NEXT make up the next one.
    next_line: bool,
}

/// A 24-bit loop sum; byte 3 marks a fallback to the float variable.
#[derive(Clone, Debug)]
struct WideSum {
    var: VarName,
    slot: String,
    top_label: String,
    checked: bool,
}

/// Per-FOR running pointer for array accesses with one loop-var axis.
/// `slot_label` names a 2-byte ZP-pointer slot that holds the live
/// address of the base shape at the current FOR counter. Use sites
/// match the same literal-axis indexes and a `loop_var + const` on the
/// live axis, then add the scaled offset from that const.
#[derive(Clone, Debug)]
struct ArrayPtrFrame {
    array_name: VarName,
    slot_label: String,
    indices: Vec<ArrayInductionIndex>,
    byte_strides: Vec<i32>,
    advance_bytes_per_step: i32,
}

/// Where a FOR loop's STEP value lives at runtime.
#[derive(Clone)]
enum StepLoc {
    /// Constant STEP — `pool_label` points at a shared MFLPT in the
    /// constant pool, and `value` lets NEXT pick its exit-sign branch
    /// at compile time (no runtime sign byte needed).
    Const { pool_label: String, value: f64 },
    /// Dynamic STEP — `slot_label` is a per-FOR MFLPT that was filled
    /// by the FOR header, and `sign_label` is the byte stamped at the
    /// same time so NEXT can pick the exit-sign branch by reading it.
    Dynamic {
        slot_label: String,
        sign_label: String,
    },
}

/// A leaf operand that the int16 fast path knows how to read with a
/// single LDA. `Imm` is split into lo/hi bytes at the use site; `Var`
/// resolves through `intern_var` to the var's slot label; `Mem` is a
/// raw 2-byte memory slot referenced by literal label (used by the
/// integer-island lowering for temporary results that don't have a
/// `VarName`).
#[derive(Clone, PartialEq, Eq)]
enum Int16Operand {
    Imm(i16),
    Var(VarName),
    Mem(String),
    /// Single-byte memory location whose 16-bit value is `(0, byte)`
    /// (high byte is implicitly zero). Generated for active u8-FOR
    /// counters (FU_<n>) — by construction the value fits in u8 and
    /// the high byte is always $00. Loaders emit `LDA <label>` for
    /// the low byte and `LDA #$00` for the high byte.
    MemU8(String),
}

/// Optimisation profile selected by the frontend. Drives the
/// size-vs-speed trade-off for any optimisation where the two pull in
/// opposite directions; pure win-win optimisations stay on under all
/// profiles.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Profile {
    /// Win-win only — every optimisation is both smaller AND faster.
    #[default]
    Default,
    /// Allow optimisations that grow the binary if they make it faster
    /// (e.g. inlined helpers, unrolled hot loops).
    Speed,
    /// Allow optimisations that shrink the binary even when slower
    /// (e.g. JSR-into-shared-helper for repeated int math).
    Size,
}

/// DATA pool layout. Decided once per program from the value mix:
/// binary entries skip the BASIC ROM VAL parser, but only work when
/// the program never READs into a string variable from this pool.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
enum DataPoolLayout {
    /// Length-prefixed ASCII. `<len>, <bytes...>`. Works for any mix
    /// of numeric and string values; READ calls `__VAL_HELPER` for
    /// numeric targets and copies the entry pointer for string ones.
    #[default]
    AsciiTagged,
    /// Fixed 2-byte little-endian i16 entries. Selected when every
    /// DATA value is an integer in `-32768..=32767` and the program
    /// has no string READ targets. READ to int = direct 2-byte
    /// load; READ to float = GIVAYF; advance = `+2`.
    BinaryI16,
    /// Five-byte BASIC floating-point entries for numeric DATA that does not fit i16.
    BinaryMflpt,
    BinaryU8,
}

/// Where the int-FOR's end value lives at runtime. Keeps the
/// fast-path bytes tight when end folds to a literal (NEXT uses
/// `CMP #imm`); falls back to a 2-byte BSS slot when the expression
/// is dynamic but range analysis proves it fits i16 (NEXT uses
/// `CMP <slot>`).
#[derive(Clone)]
enum IntForEnd {
    Literal(i16),
    Slot(String),
}

/// How the int-FOR's start value is produced. A literal start keeps
/// the counter init as two immediate stores; a dynamic start whose
/// range analysis proves it fits i16 is evaluated once into the
/// counter slot at the FOR header.
#[derive(Clone)]
enum IntForStart {
    Literal(i16),
    Dynamic,
}

#[derive(Clone)]
struct IntForFrame {
    var: VarName,
    counter_label: String,
    start_value: i16,
    /// True when the start was a dynamic expression (start_value is
    /// then a placeholder). Disables the literal-bounds shortcut in
    /// `index_provably_in_bounds`, which can't reason about it.
    dynamic_start: bool,
    end: IntForEnd,
    step_value: i16,
    /// When `Some(label)`, the step is a runtime value held in the
    /// 2-byte slot `label` (range-proved i16). NEXT then adds the slot
    /// and picks the exit direction from the slot's high-byte sign at
    /// runtime, rather than from `step_value`. Disables the literal-step
    /// strength reductions (induction / array pointers / bounds proofs).
    step_slot: Option<String>,
    top_label: String,
    exit_label: String,
    /// If false, the loop body never reads V_var, so the per-iteration
    /// sync can be skipped. We still emit one sync at the exit label so
    /// post-loop code sees the correct final value.
    body_reads_loop_var: bool,
    induction: Option<InductionFrame>,
    array_pointers: Vec<ArrayPtrFrame>,
}

/// Where a u8-FOR's end value lives. Literal ends keep the tight
/// immediate `CMP #imm`; dynamic-but-range-proved-u8 ends use the
/// first byte of an `FE_<n>` slot.
#[derive(Clone, Debug)]
enum U8ForEnd {
    Literal(u8),
    Slot(String),
}

impl U8ForEnd {
    fn literal(&self) -> Option<u8> {
        match self {
            U8ForEnd::Literal(v) => Some(*v),
            U8ForEnd::Slot(_) => None,
        }
    }
}

/// 8-bit FOR-loop frame. Counter is a single byte; loop overhead is
/// roughly 60% smaller than the 16-bit `IntForFrame`. We pick this
/// shape when start/end both fit in `[0, 255]`, the literal step fits
/// in one byte, and the selected exit mode can preserve the post-loop
/// value without byte wrap.
#[derive(Clone)]
struct U8ForFrame {
    var: VarName,
    /// 1-byte slot. Allocated in the BSS run alongside int-FOR slots,
    /// labelled `FU_<n>` so the slot table at end-of-binary
    /// distinguishes them from `FI_<n>`.
    counter_label: String,
    start_value: u8,
    end: U8ForEnd,
    /// Non-zero literal step whose magnitude fits in u8.
    step_value: i16,
    /// Exact-hit literal loops keep the old compact pre-step equality
    /// test. Non-exact or dynamic-end loops advance first, then exit
    /// after crossing the inclusive bound.
    exact_hit: bool,
    top_label: String,
    exit_label: String,
    body_reads_loop_var: bool,
    induction: Option<InductionFrame>,
    array_pointers: Vec<ArrayPtrFrame>,
}

impl ForFrame {
    fn var(&self) -> &VarName {
        match self {
            ForFrame::Float(f) => &f.var,
            ForFrame::Int(f) => &f.var,
            ForFrame::U8(f) => &f.var,
            ForFrame::U16(f, _) => &f.var,
        }
    }

    fn top_label(&self) -> &str {
        match self {
            ForFrame::Float(f) => &f.top_label,
            ForFrame::Int(f) => &f.top_label,
            ForFrame::U8(f) => &f.top_label,
            ForFrame::U16(f, _) => &f.top_label,
        }
    }

    fn exit_label(&self) -> &str {
        match self {
            ForFrame::Float(f) => &f.exit_label,
            ForFrame::Int(f) => &f.exit_label,
            ForFrame::U8(f) => &f.exit_label,
            ForFrame::U16(f, _) => &f.exit_label,
        }
    }

    fn with_fresh_exit(&self, exit_label: String) -> ForFrame {
        match self {
            ForFrame::Float(f) => {
                let mut g = f.clone();
                g.exit_label = exit_label;
                ForFrame::Float(g)
            }
            ForFrame::Int(f) => {
                let mut g = f.clone();
                g.exit_label = exit_label;
                ForFrame::Int(g)
            }
            ForFrame::U8(f) => {
                let mut g = f.clone();
                g.exit_label = exit_label;
                ForFrame::U8(g)
            }
            ForFrame::U16(f, hi) => {
                let mut g = f.clone();
                g.exit_label = exit_label;
                ForFrame::U16(g, *hi)
            }
        }
    }
}

