            writeln!(self.code, "__POKE_FILL:").unwrap();
            writeln!(self.code, "    LDX __PFL_PTR_LO").unwrap();
            writeln!(self.code, "    STX $FD").unwrap();
            writeln!(self.code, "    LDX __PFL_PTR_HI").unwrap();
            writeln!(self.code, "    STX $FE").unwrap();
            writeln!(self.code, "__PFL_PAGES:").unwrap();
            writeln!(self.code, "    LDX __PFL_CNT_HI").unwrap();
            writeln!(self.code, "    BEQ __PFL_TAIL").unwrap();
            writeln!(self.code, "    LDY #$00").unwrap();
            writeln!(self.code, "__PFL_PG_LOOP:").unwrap();
            writeln!(self.code, "    STA ($FD),Y").unwrap();
            writeln!(self.code, "    INY").unwrap();
            writeln!(self.code, "    BNE __PFL_PG_LOOP").unwrap();
            writeln!(self.code, "    INC $FE").unwrap();
            writeln!(self.code, "    DEC __PFL_CNT_HI").unwrap();
            writeln!(self.code, "    JMP __PFL_PAGES").unwrap();
            writeln!(self.code, "__PFL_TAIL:").unwrap();
            writeln!(self.code, "    LDX __PFL_CNT_LO").unwrap();
            writeln!(self.code, "    BEQ __PFL_DONE").unwrap();
            writeln!(self.code, "    LDY #$00").unwrap();
            writeln!(self.code, "__PFL_TAIL_LOOP:").unwrap();
            writeln!(self.code, "    STA ($FD),Y").unwrap();
            writeln!(self.code, "    INY").unwrap();
            writeln!(self.code, "    DEX").unwrap();
            writeln!(self.code, "    BNE __PFL_TAIL_LOOP").unwrap();
