            writeln!(self.code, "__DIM_ALLOC:").unwrap();
            writeln!(self.code, "    SEC").unwrap();
            writeln!(self.code, "    LDA __ARR_HEAP_TOP").unwrap();
            writeln!(self.code, "    SBC __DIM_BYTES_LO").unwrap();
            writeln!(self.code, "    STA __ARR_HEAP_TOP").unwrap();
