            writeln!(self.code, "    SBC __DIM_BYTES_HI").unwrap();
            writeln!(self.code, "    STA __ARR_HEAP_TOP+1").unwrap();
            writeln!(self.code, "    BCC __DIM_OOM").unwrap();
