            writeln!(self.code, "__TSB_SPR_N:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__TSB_SPR_X2:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__TSB_MASK:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__TSB_MASK_INV:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
