    writeln!(code, "    STA __MC_LEN").unwrap();
    writeln!(code, "    LDA #>$1F40").unwrap();
    writeln!(code, "    STA __MC_LEN+1").unwrap();
    writeln!(code, "    JSR __MEM_COPY").unwrap();
    writeln!(code, "    PLA").unwrap();
    writeln!(code, "    STA $01").unwrap();
    writeln!(code, "    CLI").unwrap();
    writeln!(code, "    RTS").unwrap();
    writeln!(code, "__SCR_LOAD:").unwrap();
    writeln!(code, "    LDA __SCR_MODE").unwrap();
    writeln!(code, "    BNE __SCR_LOAD_BITMAP").unwrap();
