    #[test]
    fn codegen_rejects_mismatched_structured_loop_endings() {
        let loop_until = Module {
            lines: vec![Line {
                number: 10,
                stmts: vec![
                    Stmt::Loop,
                    Stmt::Until {
                        cond: Expr::Number(1.0),
                    },
                ],
            }],
        };
        let err = emit_with_profile(&loop_until, Profile::default()).unwrap_err();
        assert!(matches!(err, CodegenError::UnmatchedUntil { line: 10 }));

        let repeat_end_loop = Module {
            lines: vec![Line {
                number: 20,
                stmts: vec![Stmt::Repeat, Stmt::EndLoop],
            }],
        };
        let err = emit_with_profile(&repeat_end_loop, Profile::default()).unwrap_err();
        assert!(matches!(err, CodegenError::UnmatchedEndLoop { line: 20 }));
    }

