    #[test]
    fn codegen_emits_computed_goto_dispatch() {
        // CGOTO with a non-literal target: must walk the line table
        // at runtime and trap UNDEFINED STATEMENT if the value
        // doesn't match any compiled line.
        let m = Module {
            lines: vec![
                Line {
                    number: 10,
                    stmts: vec![Stmt::Let {
                        var: ivar("X"),
                        value: Expr::Number(20.0),
                    }],
                },
                Line {
                    number: 20,
                    stmts: vec![Stmt::ComputedGoto {
                        target: Expr::Var(ivar("X")),
                    }],
                },
                Line {
                    number: 30,
                    stmts: vec![Stmt::End],
                },
            ],
        };

        let asm = emit_with_profile(&m, Profile::default()).unwrap();

        assert!(
            asm.contains("JMP L30") || asm.contains("JMP L20"),
            "CGOTO should dispatch to compiled line labels\n{asm}"
        );
        assert!(
            asm.contains("LDX #$11"),
            "CGOTO should retain an undefined-line error path\n{asm}"
        );
    }

    #[test]
    fn codegen_collapses_literal_computed_goto_to_jmp() {
        // CGOTO with a literal valid target: collapse to a direct
        // JMP — no FAC dance, no per-line dispatch chain.
        let m = Module {
            lines: vec![
                Line {
                    number: 10,
                    stmts: vec![Stmt::ComputedGoto {
                        target: Expr::Number(20.0),
                    }],
                },
                Line {
                    number: 20,
                    stmts: vec![Stmt::End],
                },
            ],
        };

        let asm = emit_with_profile(&m, Profile::default()).unwrap();

        assert!(
            asm.contains("JMP L20"),
            "literal CGOTO is direct JMP:\n{asm}"
        );
        // No FAC dance, no per-line CMP table, no undef-line trap
        // (the target is statically valid).
        assert!(
            !asm.contains("__CGOTO_DISPATCH"),
            "no dispatch chain for literal target:\n{asm}"
        );
    }

