    #[test]
    fn codegen_runtime_array_licm_dedups_base_guard() {
        // Three accesses to the same runtime-DIM array on a straight
        // line should emit a single \`__ARR_RT_OK\` guard — the first
        // proves BASE is non-zero, the rest skip thanks to the LICM
        // tracking.
        let n = fvar("N");
        let a = fvar("A");
        let m = Module {
            lines: vec![
                Line {
                    number: 10,
                    stmts: vec![
                        Stmt::Let {
                            var: n.clone(),
                            value: Expr::Number(5.0),
                        },
                        Stmt::Dim(vec![DimSpec {
                            name: a.clone(),
                            dims: vec![Expr::Var(n.clone())],
                        }]),
                    ],
                },
                Line {
                    number: 20,
                    stmts: vec![
                        Stmt::ArrayLet {
                            name: a.clone(),
                            indices: vec![Expr::Number(0.0)],
                            value: Expr::Number(1.0),
                        },
                        Stmt::ArrayLet {
                            name: a.clone(),
                            indices: vec![Expr::Number(1.0)],
                            value: Expr::Number(2.0),
                        },
                        Stmt::ArrayLet {
                            name: a,
                            indices: vec![Expr::Number(2.0)],
                            value: Expr::Number(3.0),
                        },
                    ],
                },
            ],
        };
        let asm = emit_with_profile(&m, Profile::default()).unwrap();
        let guards = asm.matches("__ARR_RT_OK_").count();
        // Each guard contributes 2 mentions in asm: the label
        // definition and the BNE target. So one guard = 2.
        assert!(
            guards <= 2,
            "expected at most one __ARR_RT_OK guard for three same-array \
             accesses on a straight line, got {guards}\n{asm}"
        );
    }

    #[test]
    fn codegen_runtime_array_licm_re_guards_after_branch_target() {
        // After a branch-target line we don't know the path that
        // got us there, so the validated set must reset and the
        // next access re-emits the guard.
        let n = fvar("N");
        let a = fvar("A");
        let m = Module {
            lines: vec![
                Line {
                    number: 10,
                    stmts: vec![
                        Stmt::Let {
                            var: n.clone(),
                            value: Expr::Number(5.0),
                        },
                        Stmt::Dim(vec![DimSpec {
                            name: a.clone(),
                            dims: vec![Expr::Var(n.clone())],
                        }]),
                    ],
                },
                Line {
                    number: 20,
                    stmts: vec![Stmt::ArrayLet {
                        name: a.clone(),
                        indices: vec![Expr::Number(0.0)],
                        value: Expr::Number(1.0),
                    }],
                },
                Line {
                    number: 30,
                    stmts: vec![Stmt::Goto { target: 40 }],
                },
                Line {
                    number: 40,
                    stmts: vec![Stmt::ArrayLet {
                        name: a,
                        indices: vec![Expr::Number(1.0)],
                        value: Expr::Number(2.0),
                    }],
                },
            ],
        };
        let asm = emit_with_profile(&m, Profile::default()).unwrap();
        // Two guards expected: one before line 20's access, one
        // after the GOTO target reset on line 40.
        let guard_labels = asm.matches("__ARR_RT_OK_").count();
        assert!(
            guard_labels >= 4,
            "expected at least two __ARR_RT_OK guards (one per epoch), got \
             {guard_labels} mentions\n{asm}"
        );
    }

    #[test]
    fn sqr_routes_to_rom_at_every_profile() {
        let m = Module {
            lines: vec![Line {
                number: 10,
                stmts: vec![Stmt::Let {
                    var: fvar("X"),
                    value: Expr::Func1(Func1::Sqr, Box::new(Expr::Var(fvar("Y")))),
                }],
            }],
        };
        for profile in [Profile::Default, Profile::Speed, Profile::Size] {
            let asm = emit_with_profile(&m, profile).unwrap();
            assert!(
                asm.contains("JSR $BF71"),
                "{profile:?}: SQR must call ROM $BF71:\n{asm}"
            );
            assert!(
                !asm.contains("FAST_SQRT") && !asm.contains("__SQRT_N"),
                "{profile:?}: the Newton-Raphson path must be gone entirely:\n{asm}"
            );
        }
    }

    #[test]
    fn on_key_emits_register_setup_and_poll_helper() {
        // ON KEY "Q" GOTO 100 must:
        //  * register a literal key-string pointer and length
        //  * set __ON_KEY_TARGET to L100 via lo/hi byte stamps
        //  * mark the action as GOTO, not GOSUB
        //  * raise __ON_KEY_ENABLED from $00 to $01
        //  * pull in the __ON_KEY_FIRE poll helper at finish
        let m = Module {
            lines: vec![
                Line {
                    number: 10,
                    stmts: vec![Stmt::OnKey {
                        keys: StrExpr::Literal(b"Q".to_vec()),
                        target: Some(crate::ast::OnKeyAction::Goto(100)),
                    }],
                },
                Line {
                    number: 100,
                    stmts: vec![Stmt::Rem(Vec::new())],
                },
            ],
        };
        let asm = emit_with_profile(&m, Profile::default()).unwrap();
        assert!(asm.contains("LDA #$01"), "one key byte registered:\n{asm}");
        assert!(asm.contains("STA __ON_KEY_LEN"));
        assert!(asm.contains("STA __ON_KEY_PTR"));
        assert!(asm.contains("STA __ON_KEY_PTR+1"));
        assert!(asm.contains("STA __ON_KEY_TARGET"));
        assert!(asm.contains("STA __ON_KEY_TARGET+1"));
        assert!(asm.contains("STA __ON_KEY_IS_GOSUB"));
        assert!(asm.contains("STA __ON_KEY_ENABLED"));
        assert!(
            asm.contains("__ON_KEY_FIRE:"),
            "poll helper emitted:\n{asm}"
        );
        assert!(
            asm.contains("JMP (__ON_KEY_TARGET)"),
            "indirect jump to target:\n{asm}"
        );
        assert!(!asm.contains("__ON_KEY_CHAR"));
    }

    #[test]
    fn on_key_gosub_scans_multiple_literal_keys() {
        let m = Module {
            lines: vec![
                Line {
                    number: 10,
                    stmts: vec![Stmt::OnKey {
                        keys: StrExpr::Literal(b"QW".to_vec()),
                        target: Some(crate::ast::OnKeyAction::GoSub(100)),
                    }],
                },
                Line {
                    number: 20,
                    stmts: vec![Stmt::End],
                },
                Line {
                    number: 100,
                    stmts: vec![Stmt::Return],
                },
            ],
        };
        let asm = emit_with_profile(&m, Profile::default()).unwrap();
        assert!(asm.contains("LDA #$02"), "two accepted key bytes:\n{asm}");
        assert!(asm.contains("STA __ON_KEY_LEN"));
        assert!(asm.contains("CPY __ON_KEY_LEN"));
        assert!(
            asm.contains("LDA #$01\n    STA __ON_KEY_IS_GOSUB"),
            "GOSUB mode stored:\n{asm}"
        );
        assert!(asm.contains("__ON_KEY_GOSUB:"));
        assert!(asm.contains("JSR __GOSUB_CHK"));
        assert!(!asm.contains("__ON_KEY_AFTER_GOSUB"));
        assert!(asm.contains("STX __SAVED_SP"));
        assert!(asm.contains("JMP (__ON_KEY_TARGET)"));
        assert_assembles(&asm);
    }

    #[test]
    fn on_key_inserts_poll_before_each_statement() {
        // When any ON KEY is registered, each compiled statement gets
        // a JSR-and-skip into __ON_KEY_FIRE so traps are checked inside
        // multi-statement lines as well as at line boundaries.
        let m = Module {
            lines: vec![
                Line {
                    number: 5,
                    stmts: vec![Stmt::OnKey {
                        keys: StrExpr::Literal(b"X".to_vec()),
                        target: Some(crate::ast::OnKeyAction::Goto(100)),
                    }],
                },
                Line {
                    number: 10,
                    stmts: vec![Stmt::Goto { target: 10 }],
                },
                Line {
                    number: 100,
                    stmts: vec![Stmt::Rem(Vec::new())],
                },
            ],
        };
        let asm = emit_with_profile(&m, Profile::default()).unwrap();
        // Multiple statement-level skip labels should be generated.
        assert!(
            asm.matches("__ON_KEY_SKIP_").count() >= 3,
            "statement polls emitted:\n{asm}"
        );
        assert!(
            asm.contains("LDA __ON_KEY_ENABLED"),
            "poll reads enable flag:\n{asm}"
        );
    }

    #[test]
    fn disable_clears_on_key_flag() {
        let m = Module {
            lines: vec![
                Line {
                    number: 10,
                    stmts: vec![Stmt::OnKey {
                        keys: StrExpr::Literal(b"Q".to_vec()),
                        target: Some(crate::ast::OnKeyAction::Goto(100)),
                    }],
                },
                Line {
                    number: 20,
                    stmts: vec![Stmt::Disable],
                },
                Line {
                    number: 100,
                    stmts: vec![Stmt::Rem(Vec::new())],
                },
            ],
        };
        let asm = emit_with_profile(&m, Profile::default()).unwrap();
        // DISABLE writes #$00 to the enable flag.
        let l20 = asm.split("L20:").nth(1).unwrap();
        assert!(l20.contains("LDA #$00"), "DISABLE loads zero:\n{l20}");
        assert!(l20.contains("STA __ON_KEY_ENABLED"));
    }

    #[test]
    fn on_error_installs_and_restores_the_previous_ierror_chain() {
        let m = Module {
            lines: vec![
                Line {
                    number: 10,
                    stmts: vec![Stmt::OnError { target: Some(100) }],
                },
                Line {
                    number: 20,
                    stmts: vec![Stmt::ErrorRaise {
                        code: Expr::Number(14.0),
                    }],
                },
                Line {
                    number: 30,
                    stmts: vec![Stmt::OnError { target: None }],
                },
                Line {
                    number: 100,
                    stmts: vec![Stmt::Rem(Vec::new())],
                },
            ],
        };
        let asm = emit_with_profile(&m, Profile::default()).unwrap();
        assert!(asm.contains("JMP __TSB_ERROR"));
        assert!(asm.contains("__TSB_ERROR_DEFAULT:"));
        assert!(asm.contains("JMP $A437"));
        assert!(asm.contains("LDA $0300\n    STA __TSB_IERROR_PREVIOUS+0"));
        assert!(asm.contains("LDA __TSB_IERROR_PREVIOUS+0\n    STA $0300"));
        assert!(asm.contains("LDA #<__TSB_IERROR_ENTRY\n    STA $0300"));
        let on_error = asm.split("L10:").nth(1).unwrap();
        let next_label = on_error.split("\nL").next().unwrap();
        assert!(next_label.contains("JSR __TSB_IERROR_INSTALL"));
        let no_error = asm.split("L30:").nth(1).unwrap();
        assert!(
            no_error
                .split("\nL")
                .next()
                .unwrap()
                .contains("JSR __TSB_IERROR_UNINSTALL")
        );
        assert_assembles(&asm);
    }

